const store = LUMA_OPERATION_ACCOUNTS;
const fmt = store.formatCoins;
const params = new URLSearchParams(location.search);
const item = store.accounts.find((account) => account.id === params.get("id")) || store.accounts[0];
const byId = (id) => document.getElementById(id);
const avatar = byId("avatar"), accountName = byId("accountName"), accountMeta = byId("accountMeta"), balance = byId("balance"), spentTotal = byId("spentTotal"), issued = byId("issued"), spentMonth = byId("spentMonth"), accountValue = byId("accountValue"), accountIdValue = byId("accountIdValue"), guildValue = byId("guildValue"), statusToggle = byId("statusToggle"), statusText = byId("statusText"), managementToggle = byId("managementToggle"), managementText = byId("managementText");
const editBtn = byId("editBtn"), passwordBtn = byId("passwordBtn"), recordTable = byId("recordTable"), recordCount = byId("recordCount");
const editOverlay = byId("editOverlay"), passwordOverlay = byId("passwordOverlay");
const editForm = byId("editForm"), editAvatar = byId("editAvatar"), editAvatarBtn = byId("editAvatarBtn"), editAvatarInput = byId("editAvatarInput"), nameInput = byId("nameInput"), accountInput = byId("accountInput"), guildInput = byId("guildInput");
const passwordConfirm = byId("passwordConfirm");
let uploadedAvatar = "", activeRecordTab = "issue";

guildInput.innerHTML = store.guilds.map((guild) => `<option value="${guild.id}">${guild.name} · ${guild.id}</option>`).join("");
function render() {
  avatar.textContent = item.avatar;
  accountName.textContent = item.name;
  accountMeta.textContent = item.id.replace(/\D/g, "");
  balance.textContent = fmt(item.balance);
  spentTotal.textContent = fmt(item.spentTotal);
  issued.textContent = fmt(item.issued);
  spentMonth.textContent = fmt(item.spentMonth);
  accountValue.textContent = item.account;
  accountIdValue.textContent = item.id.replace(/\D/g, "");
  guildValue.textContent = `${item.guildName} · ${item.guildId}`;
  statusToggle.checked = item.status === "enabled";
  statusText.textContent = statusToggle.checked ? "启用" : "禁用";
  managementToggle.checked = !item.managementLocked;
  managementText.textContent = managementToggle.checked ? "启用" : "禁用";
}

function renderRecords(type) {
  activeRecordTab = type;
  document.querySelectorAll("[data-record-tab]").forEach((tab) => { const active = tab.dataset.recordTab === type; tab.classList.toggle("active", active); tab.setAttribute("aria-selected", String(active)); });
  if (type === "issue") {
    const records = store.issueRecords.filter((record) => record.accountId === item.id);
    recordCount.textContent = `共 ${records.length} 条`;
    recordTable.innerHTML = `<table class="admin-table" style="min-width:860px"><thead><tr><th>发放时间</th><th>发放前余额</th><th>发放金币</th><th>发放后余额</th><th>操作人</th></tr></thead><tbody>${records.length ? records.map((record) => `<tr><td>${LUMA_FORMAT.dateTime(record.occurredAt)}</td><td class="admin-money">${fmt(record.beforeBalance)}</td><td class="admin-money">${fmt(record.amount)}</td><td class="admin-money">${fmt(record.afterBalance)}</td><td>${record.operator}</td></tr>`).join("") : '<tr><td colspan="5"><div class="admin-empty"><strong>暂无发放记录</strong></div></td></tr>'}</tbody></table>`;
    return;
  }
  const records = store.giftRecords.filter((record) => record.accountId === item.id);
  recordCount.textContent = `共 ${records.length} 条`;
  recordTable.innerHTML = `<table class="admin-table" style="min-width:1080px"><thead><tr><th>赠送时间</th><th>礼物名称</th><th>主播</th><th>礼物类型</th><th>礼物单价</th><th>赠送数量</th><th>消费金币</th></tr></thead><tbody>${records.length ? records.map((record) => `<tr><td>${LUMA_FORMAT.dateTime(record.occurredAt)}</td><td>${record.giftName}</td><td>${record.hostName}<br><span class="admin-muted">${record.hostId}</span></td><td>${record.giftType}</td><td class="admin-money">${fmt(record.unitPrice)}</td><td>${record.quantity}</td><td class="admin-money">${fmt(record.unitPrice * record.quantity)}</td></tr>`).join("") : '<tr><td colspan="7"><div class="admin-empty"><strong>暂无送礼记录</strong></div></td></tr>'}</tbody></table>`;
}

statusToggle.onchange = () => { item.status = statusToggle.checked ? "enabled" : "disabled"; render(); Luma.toast(item.status === "enabled" ? "账号已启用" : "账号已禁用"); };
managementToggle.onchange = () => { item.managementLocked = !managementToggle.checked; render(); Luma.toast(managementToggle.checked ? "公会管理权限已启用" : "公会管理权限已禁用"); };
editBtn.onclick = () => { uploadedAvatar = ""; editAvatar.textContent = item.avatar; nameInput.value = item.name; accountInput.value = item.account; guildInput.value = item.guildId; editOverlay.classList.add("show"); };
editAvatarBtn.onclick = () => editAvatarInput.click();
editAvatarInput.onchange = () => { const file = editAvatarInput.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { uploadedAvatar = reader.result; editAvatar.innerHTML = `<img src="${uploadedAvatar}" alt="头像预览" style="width:100%;height:100%;object-fit:cover;border-radius:inherit">`; }; reader.readAsDataURL(file); };
editForm.onsubmit = (event) => { event.preventDefault(); const account = accountInput.value.trim().toLowerCase(); if (store.accounts.some((candidate) => candidate !== item && candidate.account.toLowerCase() === account)) return Luma.toast("该账号已存在"); const guild = store.guilds.find((candidate) => candidate.id === guildInput.value); Object.assign(item, { name: nameInput.value.trim(), account, guildId: guild.id, guildName: guild.name, avatar: uploadedAvatar ? nameInput.value.trim().slice(0, 1).toUpperCase() : item.avatar }); editOverlay.classList.remove("show"); render(); Luma.toast("资料已保存"); };
passwordBtn.onclick = () => passwordOverlay.classList.add("show");
passwordConfirm.onclick = () => { passwordOverlay.classList.remove("show"); Luma.toast("新密码：123456"); };
document.querySelectorAll("[data-record-tab]").forEach((tab) => { tab.onclick = () => renderRecords(tab.dataset.recordTab); });
document.addEventListener("click", (event) => { const close = event.target.closest("[data-close]"); if (close) byId(close.dataset.close).classList.remove("show"); if (event.target.classList.contains("admin-overlay")) event.target.classList.remove("show"); });

render();
renderRecords("issue");
window.parent.postMessage({ type: "luma-page", file: "admin-operation-account-detail.html", query: location.search }, "*");
Luma.registerStates({ "记录": { "发放记录": () => renderRecords("issue"), "送礼记录": () => renderRecords("gift") }, "公会管理权限": { "启用": () => { managementToggle.checked = true; managementToggle.onchange(); }, "禁用": () => { managementToggle.checked = false; managementToggle.onchange(); } }, "弹窗": { "关闭": () => [editOverlay, passwordOverlay].forEach((overlay) => overlay.classList.remove("show")), "编辑资料": () => editBtn.click(), "重置密码": () => passwordBtn.click() } });

const store = LUMA_OPERATION_ACCOUNTS;
const fmt = store.formatCoins;
const accounts = store.accounts;
const keyword = document.getElementById("keyword");
const guildFilter = document.getElementById("guildFilter");
const statusFilter = document.getElementById("statusFilter");
const resetBtn = document.getElementById("resetBtn");
const searchBtn = document.getElementById("searchBtn");
const rows = document.getElementById("rows");
const resultCount = document.getElementById("resultCount");
const pagination = document.getElementById("pagination");
const displayAccount = (account) => account.id.replace(/\D/g, "");
let visible = accounts;

guildFilter.innerHTML += store.guilds.map((guild) => `<option value="${guild.id}">${guild.name}</option>`).join("");

function render(items) {
  visible = items;
  resultCount.textContent = `共 ${items.length} 个账号`;
  pagination.classList.toggle("state-hide", !items.length);
  rows.innerHTML = items.length ? items.map((account) => `<tr>
    <td><div class="admin-user-cell"><span class="admin-avatar">${account.avatar}</span><span class="admin-user-name"><b>${account.name}</b><span class="admin-muted">${displayAccount(account)}</span></span></div></td>
    <td>${account.guildName}<br><span class="admin-muted">${account.guildId}</span></td>
    <td class="admin-money">${fmt(account.spentTotal)}</td>
    <td class="admin-money">${fmt(account.balance)}</td>
    <td class="admin-money">${fmt(account.issued)}</td>
    <td class="admin-money">${fmt(account.spentMonth)}</td>
    <td><span class="admin-status ${account.status}">${account.status === "enabled" ? "启用" : "禁用"}</span></td>
    <td><a class="admin-action" href="admin-operation-account-detail.html?id=${account.id}">详情</a></td>
  </tr>`).join("") : '<tr><td colspan="8"><div class="admin-empty"><strong>未找到运营账号</strong></div></td></tr>';
}

function filter() {
  const key = keyword.value.trim().toLowerCase();
  render(accounts.filter((account) => (!key || account.name.toLowerCase().includes(key) || displayAccount(account).includes(key)) && (!guildFilter.value || account.guildId === guildFilter.value) && (!statusFilter.value || account.status === statusFilter.value)));
  Luma.toast(`已查询到 ${visible.length} 个账号`);
}

searchBtn.onclick = filter;
resetBtn.onclick = () => { keyword.value = ""; guildFilter.value = ""; statusFilter.value = ""; render(accounts); };
render(accounts);
window.parent.postMessage({ type: "luma-page", file: "admin-operation-accounts.html", query: location.search }, "*");
Luma.registerStates({ "列表状态": { "默认": () => render(accounts), "空状态": () => render([]) } });

const store = LUMA_OPERATION_ACCOUNTS, fmt = store.formatCoins, params = new URLSearchParams(location.search);
const guildFilter = document.getElementById("guildFilter"), accountFilter = document.getElementById("accountFilter"), startDate = document.getElementById("startDate"), endDate = document.getElementById("endDate"), resetBtn = document.getElementById("resetBtn"), searchBtn = document.getElementById("searchBtn"), rows = document.getElementById("rows"), resultCount = document.getElementById("resultCount"), pagination = document.getElementById("pagination"), detailOverlay = document.getElementById("detailOverlay"), detailGrid = document.getElementById("detailGrid");
const accountById = (id) => store.accounts.find((account) => account.id === id);
let visible = [];
guildFilter.innerHTML += store.guilds.map((guild) => `<option value="${guild.id}">${guild.name}</option>`).join("");
function renderAccountOptions() { const selected = accountFilter.value; const accounts = store.accounts.filter((account) => !guildFilter.value || account.guildId === guildFilter.value); accountFilter.innerHTML = '<option value="">全部账号</option>' + accounts.map((account) => `<option value="${account.id}">${account.name} · ${account.account}</option>`).join(""); if (accounts.some((account) => account.id === selected)) accountFilter.value = selected; }
function render(items) { visible = items; resultCount.textContent = `共 ${items.length} 条`; pagination.classList.toggle("state-hide", !items.length); rows.innerHTML = items.length ? items.map((record) => { const account = accountById(record.accountId); return `<tr><td><b>${account.name}</b><br><span class="admin-muted">${account.account}</span></td><td>${record.giftName}</td><td>${LUMA_FORMAT.dateTime(record.occurredAt)}</td><td>${record.hostName}<br><span class="admin-muted">${record.hostId}</span></td><td class="admin-money">${fmt(record.unitPrice * record.quantity)}</td><td><button class="admin-action" data-detail="${record.id}">详情</button></td></tr>`; }).join("") : '<tr><td colspan="6"><div class="admin-empty"><strong>未找到送礼记录</strong></div></td></tr>'; }
function filter() { render(store.giftRecords.filter((record) => { const account = accountById(record.accountId); return account && (!guildFilter.value || account.guildId === guildFilter.value) && (!accountFilter.value || record.accountId === accountFilter.value) && (!startDate.value || record.occurredAt.slice(0, 10) >= startDate.value) && (!endDate.value || record.occurredAt.slice(0, 10) <= endDate.value); }).sort((a, b) => b.occurredAt.localeCompare(a.occurredAt))); }
function openDetail(record) { const fields = [["赠送时间", LUMA_FORMAT.dateTime(record.occurredAt)], ["礼物名称", record.giftName], ["消费金币", fmt(record.unitPrice * record.quantity)], ["礼物单价", fmt(record.unitPrice)], ["礼物类型", record.giftType], ["赠送数量", fmt(record.quantity)], ["主播名称", record.hostName], ["主播ID", record.hostId]]; detailGrid.innerHTML = fields.map((field) => `<div class="admin-description-label">${field[0]}</div><div class="admin-description-value">${field[1]}</div>`).join(""); detailOverlay.classList.add("show"); }
guildFilter.onchange = () => { renderAccountOptions(); accountFilter.value = ""; };
searchBtn.onclick = filter;
resetBtn.onclick = () => { guildFilter.value = ""; renderAccountOptions(); accountFilter.value = ""; startDate.value = "2026-08-01"; endDate.value = "2026-08-29"; filter(); };
rows.onclick = (event) => { const button = event.target.closest("[data-detail]"); if (button) openDetail(visible.find((record) => record.id === button.dataset.detail)); };
document.addEventListener("click", (event) => { const close = event.target.closest("[data-close]"); if (close) document.getElementById(close.dataset.close).classList.remove("show"); if (event.target.classList.contains("admin-overlay")) event.target.classList.remove("show"); });
renderAccountOptions();
if (params.get("accountId")) { const account = accountById(params.get("accountId")); if (account) { guildFilter.value = account.guildId; renderAccountOptions(); accountFilter.value = account.id; } }
filter();
window.parent.postMessage({ type: "luma-page", file: "admin-operation-gift-records.html", query: location.search }, "*");
Luma.registerStates({ "页面状态": { "默认": filter, "送礼详情": () => { if (visible[0]) openDetail(visible[0]); }, "空状态": () => render([]) } });

const store = LUMA_OPERATION_ACCOUNTS;
const fmt = store.formatCoins;
const resultCount = document.getElementById("resultCount");
const rows = document.getElementById("rows");
const quotaOverlay = document.getElementById("quotaOverlay");
const quotaGuild = document.getElementById("quotaGuild");
const quotaForm = document.getElementById("quotaForm");
const singleLimitValue = document.getElementById("singleLimitValue");
const monthlyLimitValue = document.getElementById("monthlyLimitValue");
const guildKeyword = document.getElementById("guildKeyword");
const resetBtn = document.getElementById("resetBtn");
const searchBtn = document.getElementById("searchBtn");
let current = null;

function guildTotals(guildId) {
  return store.accounts.filter((account) => account.guildId === guildId).reduce((totals, account) => {
    totals.balance += account.balance;
    totals.spentMonth += account.spentMonth;
    return totals;
  }, { balance: 0, spentMonth: 0 });
}

function render(items = store.guilds) {
  resultCount.textContent = `共 ${items.length} 个公会`;
  rows.innerHTML = items.length ? items.map((guild) => {
    const totals = guildTotals(guild.id);
    return `<tr>
      <td><b>${guild.name}</b><br><span class="admin-muted">${guild.id}</span></td>
      <td>${fmt(guild.singleAccountMonthlyLimit)}</td>
      <td>${fmt(guild.monthlyQuota)}</td>
      <td>${fmt(guild.issued)}</td>
      <td>${fmt(totals.balance)}</td>
      <td>${fmt(totals.spentMonth)}</td>
      <td><button class="admin-action" data-quota="${guild.id}">配置额度</button></td>
    </tr>`;
  }).join("") : '<tr><td colspan="7"><div class="admin-empty"><strong>未找到公会</strong></div></td></tr>';
}

function filter() {
  const keyword = guildKeyword.value.trim().toLowerCase();
  render(store.guilds.filter((guild) => !keyword || guild.name.toLowerCase().includes(keyword) || guild.id.toLowerCase().includes(keyword)));
}

function openQuota(guild) {
  current = guild;
  quotaGuild.textContent = `${guild.name}（${guild.id}）`;
  singleLimitValue.value = guild.singleAccountMonthlyLimit;
  monthlyLimitValue.value = guild.monthlyQuota;
  quotaOverlay.classList.add("show");
}

rows.onclick = (event) => {
  const button = event.target.closest("[data-quota]");
  if (button) openQuota(store.guilds.find((guild) => guild.id === button.dataset.quota));
};

quotaForm.onsubmit = (event) => {
  event.preventDefault();
  const singleLimit = Number(singleLimitValue.value);
  const monthlyLimit = Number(monthlyLimitValue.value);
  const highestIssued = Math.max(0, ...store.accounts.filter((account) => account.guildId === current.id).map((account) => account.issued));
  if (monthlyLimit < current.issued) return Luma.toast("单月累计上限不能低于本月累计已发放");
  if (singleLimit < highestIssued) return Luma.toast("单账号上限不能低于账号本月已发放");
  if (singleLimit > monthlyLimit) return Luma.toast("单账号上限不能高于单月累计上限");
  current.singleAccountMonthlyLimit = singleLimit;
  current.monthlyQuota = monthlyLimit;
  quotaOverlay.classList.remove("show");
  filter();
  Luma.toast("额度限制已更新");
};

searchBtn.onclick = filter;
resetBtn.onclick = () => { guildKeyword.value = ""; render(); };

document.addEventListener("click", (event) => {
  const close = event.target.closest("[data-close]");
  if (close) document.getElementById(close.dataset.close).classList.remove("show");
  if (event.target.classList.contains("admin-overlay")) event.target.classList.remove("show");
});

render();
window.parent.postMessage({ type: "luma-page", file: "admin-operation-guild-controls.html" }, "*");
Luma.registerStates({ "弹窗": { "关闭": () => quotaOverlay.classList.remove("show"), "配置额度": () => openQuota(store.guilds[0]) } });

const store = LUMA_OPERATION_ACCOUNTS, fmt = store.formatCoins, params = new URLSearchParams(location.search);
const guildFilter = document.getElementById("guildFilter"), accountKeyword = document.getElementById("accountKeyword"), startDate = document.getElementById("startDate"), endDate = document.getElementById("endDate"), resetBtn = document.getElementById("resetBtn"), searchBtn = document.getElementById("searchBtn"), rows = document.getElementById("rows"), resultCount = document.getElementById("resultCount"), pagination = document.getElementById("pagination");
const accountById = (id) => store.accounts.find((account) => account.id === id);
const guildById = (id) => store.guilds.find((guild) => guild.id === id);
guildFilter.innerHTML += store.guilds.map((guild) => `<option value="${guild.id}">${guild.name}</option>`).join("");
function render(items) { resultCount.textContent = `共 ${items.length} 条`; pagination.classList.toggle("state-hide", !items.length); rows.innerHTML = items.length ? items.map((record) => { const account = accountById(record.accountId), guild = guildById(record.guildId); return `<tr><td><b>${account.name}</b><br><span class="admin-muted">${account.account}</span></td><td>${guild.name}<br><span class="admin-muted">${guild.id}</span></td><td class="admin-money">${fmt(record.beforeBalance)}</td><td class="admin-money">${fmt(record.amount)}</td><td class="admin-money">${fmt(record.afterBalance)}</td><td>${record.operator}</td><td>${LUMA_FORMAT.dateTime(record.occurredAt)}</td></tr>`; }).join("") : '<tr><td colspan="7"><div class="admin-empty"><strong>未找到发放记录</strong></div></td></tr>'; }
function filter() { const keyword = accountKeyword.value.trim().toLowerCase(); render(store.issueRecords.filter((record) => { const account = accountById(record.accountId); return (!guildFilter.value || record.guildId === guildFilter.value) && (!keyword || account.name.toLowerCase().includes(keyword) || account.id.toLowerCase().includes(keyword) || account.account.toLowerCase().includes(keyword)) && (!startDate.value || record.occurredAt.slice(0, 10) >= startDate.value) && (!endDate.value || record.occurredAt.slice(0, 10) <= endDate.value); })); }
searchBtn.onclick = filter;
resetBtn.onclick = () => { guildFilter.value = ""; accountKeyword.value = ""; startDate.value = "2026-08-01"; endDate.value = "2026-08-29"; filter(); };
if (params.get("accountId")) { const account = accountById(params.get("accountId")); if (account) { guildFilter.value = account.guildId; accountKeyword.value = account.id; } }
filter();
window.parent.postMessage({ type: "luma-page", file: "admin-operation-issue-records.html", query: location.search }, "*");
Luma.registerStates({ "列表状态": { "默认": filter, "空状态": () => render([]) } });

const R = LUMA_REPORTING,
  F = LUMA_FORMAT,
  DATA = LUMA_ADMIN_MOCK.analytics.dailyStatistics;
let visible = DATA;
const duration = (value) => {
  const hours = Math.floor(value / 60),
    minutes = value % 60;
  return `${hours ? `${hours}h ` : ""}${minutes}m`;
};
const money = (value) =>
  `<span class="statistics-recharge-money" style="color:${window.LUMA_ADMIN_TOKENS.success};font-weight:700">${F.money(value)}</span>`;
function render(items) {
  visible = items;
  pagination.classList.toggle("state-hide", !items.length);
  rows.innerHTML = items.length
    ? items
        .map(
          (item) =>
            /* HTML */ `<tr>
              <td><b>${F.date(item.date)}</b></td>
              <td>${F.integer(item.activeUsers)}</td>
              <td>${F.integer(item.newUsers)}</td>
              <td>${money(item.rechargeAmount)}</td>
              <td>${F.integer(item.rechargeUsers)}</td>
              <td>${F.integer(item.newRechargeUsers)}</td>
              <td>${money(item.newRechargeAmount)}</td>
              <td>${money(item.newUserArpu)}</td>
              <td>${F.integer(item.liveHosts)}</td>
              <td>${F.integer(item.effectiveHosts)}</td>
              <td>${duration(item.medianLiveMinutes)}</td>
              <td>${F.integer(item.refundOrderCount)}</td>
              <td>${money(item.refundAmount)}</td>
            </tr>`,
        )
        .join("")
    : '<tr><td colspan="13"><div class="admin-empty"><strong>暂无每日统计数据</strong><span>请调整筛选条件后重新查询</span></div></td></tr>';
}
function query() {
  if (!R.validateDates(startDate.value, endDate.value)) return;
  const items = DATA.filter(
    (item) =>
      (!startDate.value || item.date >= startDate.value) &&
      (!endDate.value || item.date <= endDate.value),
  );
  render(items);
  Luma.toast("已更新每日统计");
}
searchBtn.onclick = query;
resetBtn.onclick = () => {
  startDate.value = "2026-08-13";
  endDate.value = "2026-08-19";
  render(DATA);
  Luma.toast("筛选条件已重置");
};
exportBtn.onclick = () => R.exportReport("每日统计", visible.length);
render(DATA);
window.parent.postMessage(
  { type: "luma-page", file: "admin-daily-statistics.html" },
  "*",
);
Luma.registerStates({
  默认: () => {
    startDate.value = "2026-08-13";
    endDate.value = "2026-08-19";
    render(DATA);
  },
  单日数据: () => {
    startDate.value = "2026-08-19";
    endDate.value = "2026-08-19";
    query();
  },
  无查询结果: () => render([]),
});

const R = LUMA_REPORTING,
  F = LUMA_FORMAT,
  DATA = LUMA_ADMIN_MOCK.analytics.dailyStatistics,
  DEFAULT_START = "2026-08-13",
  DEFAULT_END = "2026-08-19";
const T = window.LUMA_ADMIN_TOKENS;
const metrics = [
  { key: "activeUsers", label: "活跃用户" },
  { key: "newUsers", label: "新增用户" },
  { key: "rechargeAmount", label: "总充值金额", money: true },
  { key: "rechargeUsers", label: "总充值人数" },
  { key: "newRechargeAmount", label: "新用户充值金额", money: true },
  {
    key: "newUserArpu",
    label: "新用户 ARPU",
    money: true,
    derive: (items) => {
      const users = items.reduce(
        (sum, item) => sum + item.newRechargeUsers,
        0,
      );
      return users
        ? items.reduce((sum, item) => sum + item.newRechargeAmount, 0) /
            users
        : 0;
    },
  },
  { key: "effectiveHosts", label: "达成有效天主播" },
];
let visible = DATA,
  selectedKey = "activeUsers";
const sum = (items, key) =>
  items.reduce((total, item) => total + Number(item[key] || 0), 0);
const valueFor = (metric, items) =>
  metric.derive ? metric.derive(items) : sum(items, metric.key);
const formatValue = (metric, value) =>
