const storageKey = window.LUMA_VIOLATION_TYPE_STORAGE_KEY;
let items = window.LUMA_READ_VIOLATION_TYPES(), deletingId = null;
function sharedStorage() {
  try { return window.parent && window.parent !== window ? window.parent.localStorage : localStorage; }
  catch (error) { return localStorage; }
}
function sortedItems() {
  return [...items].sort((left, right) => left.sort - right.sort || left.id.localeCompare(right.id));
}
function normalize() {
  items = sortedItems();
  items.forEach((item, index) => {
    item.sort = index + 1;
    if (item.protected) item.enabled = true;
  });
}
function saveItems() {
  try { sharedStorage().setItem(storageKey, JSON.stringify(items)); } catch (error) {}
}
function render() {
  normalize();
  resultCount.textContent = `共 ${items.length} 个类型`;
  typeRows.innerHTML = items.map((item, index) => {
    const enabled = item.protected || item.enabled;
    return /* HTML */ `<tr>
    <td>${item.id}</td>
    <td>
      <div class="violation-sort-actions">
        <span>${item.sort}</span>
        <button class="admin-icon-btn" type="button" title="上移" aria-label="上移 ${item.name}" data-move="-1" data-id="${item.id}" ${index === 0 ? "disabled" : ""}>↑</button>
        <button class="admin-icon-btn" type="button" title="下移" aria-label="下移 ${item.name}" data-move="1" data-id="${item.id}" ${index === items.length - 1 ? "disabled" : ""}>↓</button>
      </div>
    </td>
    <td><b>${item.name}</b></td>
    <td>
      <div class="admin-switch-control">
        <label class="admin-switch">
          <input type="checkbox" data-toggle="${item.id}" ${enabled ? "checked" : ""} ${item.protected ? "disabled" : ""} />
          <span class="admin-switch-track"></span>
        </label>
        <span>${enabled ? "启用" : "禁用"}</span>
      </div>
    </td>
    <td>${LUMA_FORMAT.dateTime(item.updatedAt)}</td>
    <td>
      <a class="admin-action" href="admin-violation-type-detail.html?id=${item.id}">编辑</a>
      ${item.protected ? "" : `<button class="admin-action" type="button" data-delete="${item.id}">删除</button>`}
    </td>
  </tr>`;
  }).join("");
}
typeRows.onclick = (event) => {
  const move = event.target.closest("[data-move]");
  if (move && !move.disabled) {
    const list = sortedItems(), index = list.findIndex((item) => item.id === move.dataset.id), target = index + Number(move.dataset.move);
    if (target < 0 || target >= list.length) return;
    [list[index].sort, list[target].sort] = [list[target].sort, list[index].sort];
    items = list;
    saveItems();
    render();
    Luma.toast("排序已更新");
    return;
  }
  const remove = event.target.closest("[data-delete]");
  if (!remove) return;
  const item = items.find((entry) => entry.id === remove.dataset.delete);
  if (!item || item.protected) return;
  deletingId = item.id;
  deleteText.textContent = `确认删除违规类型“${item.name}”？历史举报记录不受影响。`;
  deleteOverlay.classList.add("show");
