  if (!input) return;
  const item = items.find((entry) => entry.id === input.dataset.toggle);
  if (!item || item.protected) {
    input.checked = true;
    return;
  }
  item.enabled = input.checked;
  item.updatedAt = "2026-09-01 14:30";
  saveItems();
  render();
  Luma.toast(`违规类型已${item.enabled ? "启用" : "禁用"}`);
};
deleteForm.onsubmit = (event) => {
  event.preventDefault();
  const item = items.find((entry) => entry.id === deletingId);
  if (!item || item.protected) return;
  items = items.filter((entry) => entry.id !== deletingId);
  normalize();
  saveItems();
  deleteOverlay.classList.remove("show");
  render();
  Luma.toast("违规类型已删除");
};
