function submitAction() {
  const reasonField = document.querySelector(
      "#permissionReason,#banReason,#unbanReason",
    ),
    reason = reasonField ? reasonField.value.trim() : "";
  if (!reason) return Luma.toast("请填写操作原因");
  const time = "2026-08-04 12:00";
  if (currentAction === "permission") {
    const before = `${labels[access.platformPermission]} / ${access.locked ? "已锁定" : "未锁定"}`;
    access.platformPermission = pendingPermissionState.live
      ? "enabled"
      : "disabled";
    access.locked = !pendingPermissionState.guild;
    access.reason = reason;
    access.changedAt = time;
    access.changes.unshift({
      before,
      after: `${labels[access.platformPermission]} / ${access.locked ? "已锁定" : "未锁定"}`,
      reason,
      operator: "后台管理员",
      time,
    });
    host.permission = access.platformPermission;
  }
  if (currentAction === "ban") {
    const before = `${labels[access.platformPermission]} / ${access.locked ? "已锁定" : "未锁定"}`;
    host.accountStatus = "banned";
    host.permission = "disabled";
    access.platformPermission = "disabled";
    access.locked = true;
    access.reason = reason;
    access.changedAt = time;
    access.changes.unshift({
      before,
      after: "已关闭 / 已锁定",
      reason,
      operator: "后台管理员",
      time,
    });
    host.violations += 1;
    records.violations.unshift({
      type: "严重违规",
      action: "封禁",
      reason,
