    return `<div class="admin-checkboxes">${["银行转账", "DANA", "GoPay"].map((x) => `<label><input type="checkbox" name="channel" value="${x}" ${item.rawValue.includes(x) ? "checked" : ""}>${x}</label>`).join("")}</div>`;
