    return `<input class="admin-input" id="parameterTags" value="${item.rawValue.join("、")}" placeholder="使用顿号分隔，最多 8 个标签" required>`;
  const decimal = item.valueType === "percent";
  return `<div class="admin-setting-control"><input class="admin-input admin-number-input" id="parameterValue" type="${decimal ? "text" : "number"}" ${decimal ? 'inputmode="decimal" data-luma-decimal ' : ""}min="0.01" step="${decimal ? "0.1" : "1"}" value="${decimal ? LUMA_FORMAT.decimalInput(item.rawValue) : item.rawValue}" required><span>${item.unit || ""}</span></div>`;
