      ? LUMA_FORMAT.parseDecimal(parameterValue.value)
      : Number(parameterValue.value);
  if (item.valueType === "money") return LUMA_FORMAT.money(value);
  if (item.valueType === "rate")
    return `${LUMA_FORMAT.money(1)} = ${LUMA_FORMAT.coins(value)} 金币`;
  if (item.valueType === "earningRate")
    return `${LUMA_FORMAT.coins(value)} 金币 = ${LUMA_FORMAT.money(1)}`;
