function filterUsers() {
  const userKey = document
    .querySelector("#userKey")
    .value.trim()
    .toLowerCase();
  const phone = document
    .querySelector("#phone")
    .value.trim()
    .toLowerCase();
  const guildName = document
    .querySelector("#guildFilter")
    .value.trim()
    .toLowerCase();
  const min = Number(document.querySelector("#levelMin").value || 0);
  const max = Number(
    document.querySelector("#levelMax").value || Infinity,
  );
  const start = document.querySelector("#dateStart").value;
  const end = document.querySelector("#dateEnd").value;
  if (min > max) return Luma.toast("财富等级上限不能小于下限");
  if (start && end && start > end)
    return Luma.toast("注册结束时间不能早于开始时间");
  const filtered = allUsers.filter(
    (user) =>
      `${user.name} ${user.id}`.toLowerCase().includes(userKey) &&
      user.login.toLowerCase().includes(phone) &&
      user.guild.toLowerCase().includes(guildName) &&
      (!activeStatus || user.status === activeStatus) &&
      user.level >= min &&
      user.level <= max &&
      (!start || user.registeredAt.slice(0, 10) >= start) &&
      (!end || user.registeredAt.slice(0, 10) <= end),
  );
  render(filtered);
  Luma.toast(`已查询到 ${filtered.length} 条用户数据`);
}

