const records = LUMA_MOCK.guildPortal.joinApplications;
const params = new URLSearchParams(location.search);
const requestedReturnTab = params.get("tab");
const returnTab = ["rejected", "approved"].includes(requestedReturnTab)
  ? requestedReturnTab
  : "reviewing";
const selected =
  records.find((item) => item.id === params.get("id")) || records[0];
const storageKey = "luma-guild-join-review-results-v2";
try {
  Object.assign(
    selected,
    JSON.parse(sessionStorage.getItem(storageKey) || "{}")[selected.id] ||
      {},
  );
} catch (error) {}
backLink.href = `guild-join-review.html${returnTab === "reviewing" ? "" : `?tab=${returnTab}`}`;
function saveResult() {
  let saved = {};
  try {
    saved = JSON.parse(sessionStorage.getItem(storageKey) || "{}");
  } catch (error) {}
  saved[selected.id] = {
    status: selected.status,
    guildReviewedAt: selected.guildReviewedAt,
    reviewStage: selected.reviewStage || "",
    applicationVoided: Boolean(selected.applicationVoided),
    rejectionReason: selected.rejectionReason || "",
  };
  sessionStorage.setItem(storageKey, JSON.stringify(saved));
}
function handleReview(result, rejectionReason = "") {
  const approved = result === "approved";
  selected.status = approved ? "platformPending" : "rejected";
  selected.guildReviewedAt = "2026-08-10 11:20";
  selected.reviewStage = "guild";
  selected.applicationVoided = !approved;
  selected.rejectionReason = approved ? "" : rejectionReason;
  saveResult();
  renderDetail();
  Luma.toast(approved ? "已提交平台终审" : "申请已驳回并作废");
}
function closeApproveDialog() {
  approveDialog.classList.add("state-hide");
}
function closeRejectDialog() {
  rejectDialog.classList.add("state-hide");
}
function renderReviewTimeline() {
  const guildRejected =
    selected.status === "rejected" && selected.reviewStage === "guild";
  const platformRejected =
    selected.status === "rejected" && selected.reviewStage === "platform";
  const guildCompleted = selected.status !== "pending";
  const platformCompleted = ["approved", "rejected"].includes(
    selected.status,
  ) && selected.reviewStage === "platform";
  const joined = selected.status === "approved";
  const guildState = guildRejected
    ? "is-rejected"
