const params = new URLSearchParams(location.search);
const dataModel = LUMA_GUILD_DATA;
const requestedHostValue = params.has("hostIds")
  ? params.get("hostIds")
  : params.get("hostId") || params.get("id") || "all";
const noHostsSelected = requestedHostValue === "none";
const requestedHostIds = requestedHostValue
  .split(",")
  .filter((id) => dataModel.hosts.some((host) => host.id === id));
const selectedHosts = noHostsSelected
  ? []
  : requestedHostValue === "all" || !requestedHostIds.length
    ? dataModel.hosts
    : dataModel.hosts.filter((host) =>
        requestedHostIds.includes(host.id),
      );
const sourceSummaries = selectedHosts.map((item) =>
  dataModel.getSummary(item.id),
);
const completeSummary =
  sourceSummaries[0] || dataModel.getSummary(dataModel.hosts[0].id);
const isAllHosts = selectedHosts.length === dataModel.hosts.length;
const isSingleHost = selectedHosts.length === 1;
const host = selectedHosts[0] || {
  id: "none",
  name: "未选择主播",
  avatar: "无",
  live: false,
};
const currentMonth = completeSummary.days[0].date.slice(0, 7);
const availableMonths = [
  ...new Set(completeSummary.days.map((day) => day.date.slice(0, 7))),
]
  .sort()
  .reverse();
const selectedMonth = availableMonths.includes(params.get("hostPeriod"))
  ? params.get("hostPeriod")
  : currentMonth;
const allDates = completeSummary.days.map((day) => day.date).sort();
const allDateSet = new Set(allDates);
const selectedMonthDates = allDates.filter((date) =>
  date.startsWith(selectedMonth),
);
const requestedRangeStart = params.get("rangeStart");
const requestedRangeEnd = params.get("rangeEnd");
const rangeStart = allDateSet.has(requestedRangeStart)
  ? requestedRangeStart
  : selectedMonthDates[0];
const rangeEnd =
  allDateSet.has(requestedRangeEnd) && requestedRangeEnd >= rangeStart
    ? requestedRangeEnd
    : selectedMonthDates[selectedMonthDates.length - 1];
const selectedDays = sourceSummaries.flatMap((item) =>
  item.days
    .filter((day) => day.date >= rangeStart && day.date <= rangeEnd)
    .map((day) => ({ ...day, host: item.host })),
);
const summary = selectedDays.reduce(
  (result, day) => {
    result.coins += day.coins;
    result.gifts += day.gifts;
    result.fans += day.fans;
    result.sessions += day.sessionCount;
    result.effectiveDays += day.effective ? 1 : 0;
    result.duration += day.duration;
    return result;
  },
  {
    coins: 0,
    gifts: 0,
    fans: 0,
    sessions: 0,
    effectiveDays: 0,
    duration: 0,
  },
);
const origin = [
  "overview",
  "detail",
  "income",
  "operations",
  "list",
  "summary",
].includes(params.get("from"))
  ? params.get("from")
  : "home";
const summaryFrom = ["list", "operations"].includes(
  params.get("summaryFrom"),
)
  ? params.get("summaryFrom")
  : "home";
const summaryView =
  params.get("summaryView") === "month" ? "month" : "day";
const returnDate = dataModel.dates.includes(params.get("returnDate"))
  ? params.get("returnDate")
  : dataModel.dates[dataModel.dates.length - 1];
const returnPeriod = params.get("returnPeriod");
const returnSource = ["home", "income", "host-month"].includes(
  params.get("returnSource"),
)
  ? params.get("returnSource")
  : "income";
let pendingRangeStart = rangeStart;
let pendingRangeEnd = rangeEnd;
let calendarMonth = rangeEnd.slice(0, 7);

function operationContext() {
  if (origin !== "operations") return "";
  const query = new URLSearchParams({ returnDate, returnSource });
  if (returnPeriod) query.set("returnPeriod", returnPeriod);
  return `&${query}`;
}

function applyHostSelection(query) {
  query.delete("id");
  query.delete("hostId");
  query.delete("hostIds");
  if (noHostsSelected) query.set("hostIds", "none");
  else if (isAllHosts) query.set("hostId", "all");
  else
    query.set("hostIds", selectedHosts.map((item) => item.id).join(","));
  return query;
}

function renderHostPicker() {
  if (isSingleHost) {
    hostSwitchLink.innerHTML = `<span><b>${host.name}</b><small>${host.id}</small></span><strong class="guild-selected-host-count">已选1人</strong><em aria-hidden="true">›</em>`;
    hostSwitchLink.setAttribute(
      "aria-label",
      `选择主播，当前${host.name}，${host.id}，已选1人`,
    );
  } else {
    hostSwitchLink.innerHTML = `<span><b>主播</b></span><strong class="guild-selected-host-count">已选${selectedHosts.length}人</strong><em aria-hidden="true">›</em>`;
    hostSwitchLink.setAttribute(
      "aria-label",
      `选择主播，已选${selectedHosts.length}人`,
    );
  }
  const selectParams = new URLSearchParams(location.search);
  selectParams.delete("hostId");
  selectParams.delete("hostIds");
  selectParams.set("pickerTarget", "live");
  if (noHostsSelected) selectParams.set("selected", "none");
  else if (!isAllHosts)
    selectParams.set(
      "selected",
      selectedHosts.map((item) => item.id).join(","),
    );
  else selectParams.delete("selected");
  hostSwitchLink.href = `guild-violation-host-select.html?${selectParams}`;
}

function summaryReturnUrl() {
  const query = new URLSearchParams({
    hostId: host.id,
    from: summaryFrom,
    hostPeriod: selectedMonth,
    view: summaryView,
  });
  if (summaryFrom === "operations") {
    query.set("returnDate", returnDate);
    query.set("returnSource", returnSource);
    if (returnPeriod) query.set("returnPeriod", returnPeriod);
  }
  return `guild-host-summary.html?${query}`;
}

