const shortcutLabels = {
  today: "今日",
  yesterday: "昨日",
  thisWeek: "本周",
  lastWeek: "上周",
  thisMonth: "本月",
  lastMonth: "上月",
  custom: "自定义",
};
const dateFromValue = (value) => new Date(`${value}T12:00:00`);
const dateValue = (date) =>
  `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const addDays = (date, amount) => {
  const value = new Date(date);
  value.setDate(value.getDate() + amount);
  return value;
};
const dataToday = dateFromValue(allDates[allDates.length - 1]);

function normalizeRange(start, end) {
  const dates = allDates.filter((date) => date >= start && date <= end);
  return dates.length
    ? [dates[0], dates[dates.length - 1]]
    : [start, end];
}

function shortcutRange(shortcut) {
  const weekday = dataToday.getDay() || 7;
  const thisWeekStart = addDays(dataToday, 1 - weekday);
  if (shortcut === "yesterday") {
    const day = dateValue(addDays(dataToday, -1));
    return normalizeRange(day, day);
  }
  if (shortcut === "thisWeek")
    return normalizeRange(dateValue(thisWeekStart), dateValue(dataToday));
  if (shortcut === "lastWeek")
    return normalizeRange(
      dateValue(addDays(thisWeekStart, -7)),
      dateValue(addDays(thisWeekStart, -1)),
    );
  if (shortcut === "thisMonth")
    return normalizeRange(
      dateValue(
        new Date(dataToday.getFullYear(), dataToday.getMonth(), 1, 12),
      ),
      dateValue(dataToday),
    );
  if (shortcut === "lastMonth")
    return normalizeRange(
      dateValue(
        new Date(
          dataToday.getFullYear(),
          dataToday.getMonth() - 1,
          1,
          12,
        ),
      ),
      dateValue(
        new Date(dataToday.getFullYear(), dataToday.getMonth(), 0, 12),
      ),
    );
  const today = dateValue(dataToday);
  return normalizeRange(today, today);
}

function activeShortcut() {
  return (
    [
      "today",
      "yesterday",
      "thisWeek",
      "lastWeek",
      "thisMonth",
      "lastMonth",
    ].find((shortcut) => {
      const [start, end] = shortcutRange(shortcut);
      return start === rangeStart && end === rangeEnd;
    }) || "custom"
  );
}

