function dateObject(value) {
  const [year, month, day] = value.split("-").map(Number);
  return new Date(year, month - 1, day, 12);
}

function dateValue(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function offsetDate(date, days) {
  const value = new Date(date);
  value.setDate(value.getDate() + days);
  return value;
}

function shortcutRange(shortcut) {
  const latest = dateObject(latestDate);
  const weekdayOffset = (latest.getDay() + 6) % 7;
  if (shortcut === "thisWeek")
    return [dateValue(offsetDate(latest, -weekdayOffset)), latestDate];
  if (shortcut === "lastWeek") {
    const end = offsetDate(latest, -weekdayOffset - 1);
    return [dateValue(offsetDate(end, -6)), dateValue(end)];
  }
  if (shortcut === "lastMonth") {
    return [
      dateValue(
        new Date(latest.getFullYear(), latest.getMonth() - 1, 1, 12),
      ),
      dateValue(new Date(latest.getFullYear(), latest.getMonth(), 0, 12)),
    ];
  }
  return [
    dateValue(new Date(latest.getFullYear(), latest.getMonth(), 1, 12)),
    latestDate,
  ];
}

const shortcutKeys = Object.keys(shortcutLabels);
