  <i aria-hidden="true">›</i>
</a>`;
}

function monthlyRows() {
  const groups = completeSummary.days.reduce((result, day) => {
    const month = day.date.slice(0, 7);
    if (!result.has(month)) result.set(month, []);
    result.get(month).push(day);
    return result;
  }, new Map());
  return [...groups.entries()]
    .sort(([left], [right]) => right.localeCompare(left))
    .map(([month, days]) => {
      const summary = summarize(days);
      const dates = days.map((day) => day.date).sort();
      const [year, value] = month.split("-");
      const query = new URLSearchParams({
        hostId: host.id,
        from: "summary",
        summaryFrom: origin,
        summaryView: "month",
        hostPeriod: month,
        rangeStart: dates[0],
        rangeEnd: dates[dates.length - 1],
      });
      if (origin === "operations") {
        query.set("returnDate", returnDate);
        query.set("returnSource", returnSource);
        if (returnPeriod) query.set("returnPeriod", returnPeriod);
      }
      return `<a class="guild-host-daily-row guild-host-monthly-row" role="row" href="guild-host-data.html?${query}">
    <span role="cell">${value}/${year}</span>
    <span role="cell">${dataModel.formatDuration(summary.duration)}</span>
    <span class="guild-signed-value ${dataModel.signClass(summary.fans)}" role="cell">${dataModel.formatSignedInteger(summary.fans)}</span>
    <strong role="cell"><svg class="guild-coin-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 21 12 12 21 3 12Z"></path></svg>${LUMA_FORMAT.coins(summary.coins)}</strong>
    <i aria-hidden="true">›</i>
  </a>`;
    })
    .join("");
}

function applyRange(start, end, shortcut = null) {
  const nextParams = new URLSearchParams(location.search);
  nextParams.set("hostId", host.id);
  nextParams.set("from", origin);
  nextParams.set("hostPeriod", end.slice(0, 7));
  nextParams.set("rangeStart", start);
  nextParams.set("rangeEnd", end);
  if (shortcut) nextParams.set("shortcut", shortcut);
  else nextParams.delete("shortcut");
  location.href = `guild-host-summary.html?${nextParams}`;
}

function shiftMonth(month, offset) {
  const [year, value] = month.split("-").map(Number);
  return dateValue(new Date(year, value - 1 + offset, 1, 12)).slice(0, 7);
}

function renderCalendar() {
  const [yearText, monthText] = calendarMonth.split("-");
  const year = Number(yearText);
  const month = Number(monthText);
  const firstWeekday = new Date(year, month - 1, 1).getDay();
  const dayCount = new Date(year, month, 0).getDate();
  calendarTitle.textContent = `${month}/${year}`;
  calendarPrev.disabled = shiftMonth(calendarMonth, -1) < earliestMonth;
  calendarNext.disabled = shiftMonth(calendarMonth, 1) > latestMonth;
  const blanks = Array.from(
    { length: firstWeekday },
    () => '<span aria-hidden="true"></span>',
  ).join("");
  const days = Array.from({ length: dayCount }, (_, index) => {
    const date = `${yearText}-${monthText}-${String(index + 1).padStart(2, "0")}`;
    const enabled = allDateSet.has(date);
    const isStart = date === pendingRangeStart;
    const isEnd = date === pendingRangeEnd;
    const inRange =
      pendingRangeStart &&
      pendingRangeEnd &&
      date > pendingRangeStart &&
      date < pendingRangeEnd;
    const classes = [
      isStart ? "range-start" : "",
      isEnd ? "range-end" : "",
      inRange ? "in-range" : "",
    ]
      .filter(Boolean)
      .join(" ");
    return `<button class="${classes}" type="button" role="gridcell" data-date="${date}" aria-selected="${Boolean(isStart || isEnd || inRange)}"${enabled ? "" : " disabled"}>${index + 1}</button>`;
  }).join("");
  calendarDays.innerHTML = blanks + days;
  const end = pendingRangeEnd || pendingRangeStart;
  rangeSelection.textContent = pendingRangeStart
    ? `${LUMA_FORMAT.date(pendingRangeStart)}～${LUMA_FORMAT.date(end)}`
    : "请选择日期";
}

