function drawTrend() {
  const metric = currentView().metrics.find(
    (item) => item.key === activeMetric,
  );
  const values = metric.values;
  const width = 340,
    height = 140,
    left = 42,
    right = 8,
    top = 14,
    bottom = 26;
  const plotWidth = width - left - right,
    plotHeight = height - top - bottom;
  const max = Math.max(...values, 1);
  const x = (index) =>
    left + (plotWidth * index) / Math.max(values.length - 1, 1);
  const y = (value) => top + plotHeight - (value / max) * plotHeight;
  const grids = [0, 1, 2]
    .map((index) => {
      const lineY = top + (plotHeight * index) / 2;
      const value = max - (max * index) / 2;
      return `<line class="grid-line" x1="${left}" y1="${lineY}" x2="${width - right}" y2="${lineY}"></line><text class="axis-label" x="${left - 6}" y="${lineY + 3}" text-anchor="end">${metric.format(Math.round(value))}</text>`;
    })
    .join("");
  const points = values
    .map((value, index) => `${x(index)},${y(value)}`)
    .join(" ");
  const every =
    currentMode === "month"
      ? Math.max(1, Math.ceil(values.length / 6))
      : Math.max(1, Math.ceil(values.length / 5));
  const dots = values
    .map((value, index) =>
      index % every === 0 || index === values.length - 1
        ? `<circle class="trend-point" cx="${x(index)}" cy="${y(value)}" r="2.6"></circle>`
        : "",
    )
    .join("");
  const labels = metric.labels
    .map((label, index) =>
      index % every === 0 || index === metric.labels.length - 1
        ? `<text class="axis-label" x="${x(index)}" y="136" text-anchor="middle">${label}</text>`
        : "",
    )
    .join("");
  trendPlot = values.map((value, index) => ({
    label: metric.labels[index],
    value,
    x: x(index),
    y: y(value),
  }));
  incomeTrend.setAttribute("aria-label", `${metric.label}趋势`);
  incomeTrend.innerHTML = `${grids}<line class="trend-hover-line" y1="${top}" y2="${top + plotHeight}" hidden></line><polyline class="trend-line" points="${points}"></polyline>${dots}<circle class="trend-hover-point" r="4" hidden></circle>${labels}`;
}

function showTrendTooltip(event) {
  const rect = incomeTrend.getBoundingClientRect();
  const pointerX = ((event.clientX - rect.left) / rect.width) * 340;
  const nearest = trendPlot.reduce((current, point) => {
    const distance = Math.abs(point.x - pointerX);
    return !current || distance < current.distance
      ? { point, distance }
      : current;
  }, null)?.point;
  if (!nearest) return;
  const metric = currentView().metrics.find(
    (item) => item.key === activeMetric,
  );
  const line = incomeTrend.querySelector(".trend-hover-line");
  const point = incomeTrend.querySelector(".trend-hover-point");
  line.setAttribute("x1", nearest.x);
  line.setAttribute("x2", nearest.x);
  line.removeAttribute("hidden");
  point.setAttribute("cx", nearest.x);
  point.setAttribute("cy", nearest.y);
  point.removeAttribute("hidden");
  trendTooltipDate.textContent = `${currentMode === "day" ? "日期" : "月份"} ${nearest.label}`;
  trendTooltipValue.textContent = `${metric.label} ${metric.format(nearest.value)}`;
  incomeTrendTooltip.style.left = `${Math.max(62, Math.min(rect.width - 62, (nearest.x / 340) * rect.width))}px`;
  incomeTrendTooltip.style.top = `${Math.max(48, (nearest.y / 140) * rect.height)}px`;
  incomeTrendTooltip.hidden = false;
}

function hideTrendTooltip() {
  incomeTrendTooltip.hidden = true;
  incomeTrend
