function applyRange(start, end, shortcut = null) {
  const nextParams = new URLSearchParams(location.search);
  nextParams.set("mode", "day");
  nextParams.set("period", end.slice(0, 7));
  nextParams.set("rangeStart", start);
  nextParams.set("rangeEnd", end);
  if (shortcut) nextParams.set("shortcut", shortcut);
  else nextParams.delete("shortcut");
  location.href = `guild-income.html?${nextParams}`;
}

function applyMonthRange(start, end, shortcut = null) {
  const nextParams = new URLSearchParams(location.search);
  nextParams.set("mode", "month");
  nextParams.set("monthStart", start);
  nextParams.set("monthEnd", end);
  if (shortcut) nextParams.set("monthShortcut", shortcut);
  else nextParams.delete("monthShortcut");
  location.href = `guild-income.html?${nextParams}`;
}

function shiftMonth(month, offset) {
  const [year, value] = month.split("-").map(Number);
  return dateValue(new Date(year, value - 1 + offset, 1, 12)).slice(0, 7);
}

function renderCalendar() {
  const [yearText, monthText] = calendarMonth.split("-");
  const year = Number(yearText);
  const month = Number(monthText);
  const firstWeekday = new Date(year, month - 1, 1).getDay();
  const dayCount = new Date(year, month, 0).getDate();
  calendarTitle.textContent = `${month}/${year}`;
  calendarPrev.disabled = shiftMonth(calendarMonth, -1) < earliestMonth;
  calendarNext.disabled = shiftMonth(calendarMonth, 1) > latestMonth;
  const blanks = Array.from(
    { length: firstWeekday },
    () => '<span aria-hidden="true"></span>',
  ).join("");
  const days = Array.from({ length: dayCount }, (_, index) => {
    const date = `${yearText}-${monthText}-${String(index + 1).padStart(2, "0")}`;
    const enabled = allDateSet.has(date);
    const isStart = date === pendingRangeStart;
    const isEnd = date === pendingRangeEnd;
    const inRange =
      pendingRangeStart &&
      pendingRangeEnd &&
      date > pendingRangeStart &&
      date < pendingRangeEnd;
    const classes = [
      isStart ? "range-start" : "",
      isEnd ? "range-end" : "",
      inRange ? "in-range" : "",
    ]
      .filter(Boolean)
      .join(" ");
    return `<button class="${classes}" type="button" role="gridcell" data-date="${date}" aria-selected="${Boolean(isStart || isEnd || inRange)}"${enabled ? "" : " disabled"}>${index + 1}</button>`;
  }).join("");
  calendarDays.innerHTML = blanks + days;
  const end = pendingRangeEnd || pendingRangeStart;
  rangeSelection.textContent = pendingRangeStart
    ? `${LUMA_FORMAT.date(pendingRangeStart)}～${LUMA_FORMAT.date(end)}`
    : "请选择日期";
}

function openRangeSheet() {
  pendingRangeStart = rangeStart;
  pendingRangeEnd = rangeEnd;
  calendarMonth = rangeEnd.slice(0, 7);
  renderCalendar();
  rangeSheet.hidden = false;
  document.body.classList.add("guild-sheet-open");
}

function closeRangeSheet() {
  rangeSheet.hidden = true;
  document.body.classList.remove("guild-sheet-open");
  rangePickerButton.focus();
}

function closeShortcutMenu() {
  shortcutMenu.hidden = true;
  shortcutPicker.setAttribute("aria-expanded", "false");
}

function renderMonthCalendar() {
  const earliestAvailableMonth =
    availableMonths[availableMonths.length - 1];
  const earliestYear = Number(earliestAvailableMonth.slice(0, 4));
  const latestYear = Number(latestMonth.slice(0, 4));
  monthCalendarTitle.textContent = `${monthCalendarYear}年`;
  monthCalendarPrev.disabled = monthCalendarYear <= earliestYear;
  monthCalendarNext.disabled = monthCalendarYear >= latestYear;
  monthCalendarMonths.innerHTML = Array.from(
    { length: 12 },
    (_, index) => {
      const month = `${monthCalendarYear}-${String(index + 1).padStart(2, "0")}`;
      const enabled =
        month >= earliestAvailableMonth && month <= latestMonth;
      const isStart = month === pendingMonthRangeStart;
      const isEnd = month === pendingMonthRangeEnd;
      const inRange =
        pendingMonthRangeStart &&
        pendingMonthRangeEnd &&
        month > pendingMonthRangeStart &&
        month < pendingMonthRangeEnd;
      const classes = [
        isStart ? "range-start" : "",
        isEnd ? "range-end" : "",
        inRange ? "in-range" : "",
      ]
        .filter(Boolean)
        .join(" ");
      return `<button class="${classes}" type="button" role="gridcell" data-month="${month}" aria-selected="${Boolean(isStart || isEnd || inRange)}"${enabled ? "" : " disabled"}>${index + 1}月</button>`;
    },
  ).join("");
  const end = pendingMonthRangeEnd || pendingMonthRangeStart;
  monthRangeHint.textContent = pendingMonthRangeStart
    ? `${displayMonth(pendingMonthRangeStart)}～${displayMonth(end)}`
    : "请选择月份";
}

function openMonthRangeSheet() {
  pendingMonthRangeStart = monthRangeStart;
  pendingMonthRangeEnd = monthRangeEnd;
  monthCalendarYear = Number(monthRangeEnd.slice(0, 4));
