};
rangeSheet.onclick = (event) => {
  if (event.target === rangeSheet) closeRangeSheet();
};
monthRangeSheetCancel.onclick = closeMonthRangeSheet;
monthRangeSheetConfirm.onclick = () => {
  if (!pendingMonthRangeStart) return;
  applyMonthRange(
    pendingMonthRangeStart,
    pendingMonthRangeEnd || pendingMonthRangeStart,
  );
};
monthRangeSheet.onclick = (event) => {
  if (event.target === monthRangeSheet) closeMonthRangeSheet();
};
monthCalendarPrev.onclick = () => {
  const earliestYear = Number(
    availableMonths[availableMonths.length - 1].slice(0, 4),
  );
  if (monthCalendarYear <= earliestYear) return;
  monthCalendarYear -= 1;
  renderMonthCalendar();
};
monthCalendarNext.onclick = () => {
  const latestYear = Number(latestMonth.slice(0, 4));
  if (monthCalendarYear >= latestYear) return;
  monthCalendarYear += 1;
  renderMonthCalendar();
};
monthCalendarMonths.onclick = (event) => {
  const option = event.target.closest("[data-month]");
  if (!option || option.disabled) return;
  const month = option.dataset.month;
  if (!pendingMonthRangeStart || pendingMonthRangeEnd) {
    pendingMonthRangeStart = month;
    pendingMonthRangeEnd = null;
  } else if (month < pendingMonthRangeStart) {
    pendingMonthRangeEnd = pendingMonthRangeStart;
    pendingMonthRangeStart = month;
  } else {
    pendingMonthRangeEnd = month;
  }
  renderMonthCalendar();
};
calendarPrev.onclick = () => {
  const next = shiftMonth(calendarMonth, -1);
  if (next < earliestMonth) return;
  calendarMonth = next;
  renderCalendar();
};
calendarNext.onclick = () => {
  const next = shiftMonth(calendarMonth, 1);
  if (next > latestMonth) return;
  calendarMonth = next;
  renderCalendar();
};
calendarDays.onclick = (event) => {
  const option = event.target.closest("[data-date]");
  if (!option || option.disabled) return;
  const date = option.dataset.date;
  if (!pendingRangeStart || pendingRangeEnd) {
    pendingRangeStart = date;
    pendingRangeEnd = null;
  } else if (date < pendingRangeStart) {
    pendingRangeEnd = pendingRangeStart;
    pendingRangeStart = date;
  } else {
    pendingRangeEnd = date;
  }
  renderCalendar();
};
