  const weekdayOffset = (today.getDay() + 6) % 7;
  if (shortcut === "thisWeek")
    return [dateValue(offsetDate(today, -weekdayOffset)), todayValue];
  if (shortcut === "lastWeek") {
    const lastWeekEnd = offsetDate(today, -weekdayOffset - 1);
    return [
      dateValue(offsetDate(lastWeekEnd, -6)),
      dateValue(lastWeekEnd),
    ];
  }
  if (shortcut === "thisMonth")
    return [
      dateValue(new Date(today.getFullYear(), today.getMonth(), 1, 12)),
      todayValue,
    ];
  if (shortcut === "lastMonth")
    return [
      dateValue(
        new Date(today.getFullYear(), today.getMonth() - 1, 1, 12),
      ),
      dateValue(new Date(today.getFullYear(), today.getMonth(), 0, 12)),
    ];
  return [todayValue, todayValue];
}
