function calendarDate(year, month, day) {
  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}
function renderCalendar() {
  const [yearText, monthText] = calendarMonth.split("-");
  const year = Number(yearText);
  const month = Number(monthText);
  const firstWeekday = new Date(year, month - 1, 1).getDay();
  const dayCount = new Date(year, month, 0).getDate();
  calendarTitle.textContent = `${month}/${year}`;
  const blanks = Array.from(
    { length: firstWeekday },
    () => '<span aria-hidden="true"></span>',
  ).join("");
  const days = Array.from({ length: dayCount }, (_, index) => {
    const date = calendarDate(year, month, index + 1);
    const disabled = date > todayValue;
    const isStart = date === pendingRangeStart;
    const isEnd = date === pendingRangeEnd;
    const inRange =
      pendingRangeStart &&
      pendingRangeEnd &&
      date > pendingRangeStart &&
      date < pendingRangeEnd;
    const classes = [
      isStart ? "range-start" : "",
      isEnd ? "range-end" : "",
      inRange ? "in-range" : "",
    ]
      .filter(Boolean)
      .join(" ");
    return `<button class="${classes}" type="button" role="gridcell" data-date="${date}" aria-selected="${isStart || isEnd || inRange}"${disabled ? " disabled" : ""}>${index + 1}</button>`;
  }).join("");
  calendarDays.innerHTML = blanks + days;
  rangeSelection.textContent = pendingRangeStart
    ? pendingRangeEnd
      ? `${displayDate(pendingRangeStart)}～${displayDate(pendingRangeEnd)}`
      : `已选开始日期：${displayDate(pendingRangeStart)}`
    : "请选择开始日期";
}
