let activeStatus = "active";
function departedIds() {
  return new Set([
    ...approvedDepartures.map((item) => item.id),
    ...formerHosts.map((item) => item.id),
    ...removedHostIds,
  ]);
}
function statusHosts() {
  const ids = departedIds();
  if (activeStatus === "active")
    return currentHosts.filter((item) => !ids.has(item.id));
  const departed = new Map(
    formerHosts.map((item) => [item.id, item]),
