const authDraftKey = "luma-auth-phone-draft";
const regionDefaults = {
  ID: ["🇮🇩", "+62"],
  MY: ["🇲🇾", "+60"],
  US: ["🇺🇸", "+1"],
  CA: ["🇨🇦", "+1"],
  SG: ["🇸🇬", "+65"],
  TH: ["🇹🇭", "+66"],
  PH: ["🇵🇭", "+63"],
  VN: ["🇻🇳", "+84"],
  JP: ["🇯🇵", "+81"],
  KR: ["🇰🇷", "+82"],
  IN: ["🇮🇳", "+91"],
  AU: ["🇦🇺", "+61"],
  GB: ["🇬🇧", "+44"],
};
function parseDraft() {
  try {
    return JSON.parse(sessionStorage.getItem(authDraftKey)) || {};
  } catch (_error) {
    return {};
  }
}
function deviceCountry() {
  const locale = navigator.languages?.[0] || navigator.language || "";
  const region = locale.match(/[-_]([A-Za-z]{2})\b/)?.[1]?.toUpperCase();
  return regionDefaults[region] || regionDefaults.ID;
}
function setCountry(flag, dialCode) {
  countryFlag.textContent = flag || "🌐";
  countryDial.textContent = dialCode && dialCode !== "+86" ? dialCode : "+62";
}
const savedDraft = parseDraft();
const [defaultFlag, defaultDial] = deviceCountry();
const savedDial = savedDraft.dialCode === "+86" ? "" : savedDraft.dialCode;
setCountry(savedDial ? savedDraft.flag : defaultFlag, savedDial || defaultDial);
phone.value = savedDraft.phone || "";
agreement.checked = Boolean(savedDraft.agreement);
if (savedDraft.loginMethod === "password") loginMethod = "password";

countryCode.onclick = () => {
  sessionStorage.setItem(
    authDraftKey,
    JSON.stringify({
      phone: phone.value.trim(),
      agreement: agreement.checked,
      loginMethod,
      flag: countryFlag.textContent,
      dialCode: countryDial.textContent,
    }),
  );
  window.parent.postMessage(
    { type: "luma-page", file: "auth-country-select.html" },
    "*",
  );
  location.href = "auth-country-select.html";
};
function phoneValid() {
  return /^\d{8,15}$/.test(phone.value.trim());
}
function syncSubmit() {
  const credentialValid =
    loginMethod === "code"
      ? /^\d{6}$/.test(code.value.trim())
      : Boolean(password.value);
  submit.disabled = !(
    phoneValid() &&
    credentialValid &&
    agreement.checked
  );
  sendCode.disabled =
    loginMethod !== "code" || !phoneValid() || Boolean(countdownTimer);
}
function setLoginMethod(method) {
  loginMethod = method;
  document
    .querySelector("#codeField")
    .classList.toggle("state-hide", method !== "code");
  document
    .querySelector("#passwordField")
    .classList.toggle("state-hide", method !== "password");
  document.querySelector("#methodSwitch").textContent =
    method === "code" ? "使用密码登录" : "使用短信验证码登录";
  syncSubmit();
}
