let keyword = params.get("keyword") || (managerMode ? "" : "620100");
if (managerMode) input.placeholder = "搜索用户 ID";
const resultUrl = (value) => {
  const query = new URLSearchParams({ keyword: value });
  if (managerMode) {
    query.set("mode", "manager");
    query.set("return", returnTarget);
  }
  return `search-results.html?${query}`;
};
function render(value) {
  keyword = value.trim();
  input.value = keyword;
  const normalized = keyword.toLowerCase();
  const matches = entries.filter((item) =>
    (managerMode
      ? [item.id, item.name]
      : [item.id, item.name, item.isHost ? item.roomId : ""]
    )
      .filter(Boolean)
      .some((field) => String(field).toLowerCase().includes(normalized)),
  );
  title.textContent = `“${keyword}” 的搜索结果`;
  list.classList.toggle("state-hide", !matches.length);
  empty.classList.toggle("state-hide", Boolean(matches.length));
  list.innerHTML = matches
    .map((item) => {
      if (managerMode)
        return `<article class="result"><button class="avatar avatar-action" type="button" data-manager-id="${item.id}" aria-label="查看 ${item.name} 的资料卡">${item.avatar}</button><span class="result-info"><b>${item.name}</b><span>ID：${item.id}</span></span><button class="live-entry" type="button" data-manager-id="${item.id}">查看资料</button></article>`;
      const liveTarget = `../live/live-room.html?room=${encodeURIComponent(item.roomId)}`;
      const isLive = item.isHost && item.live;
      const profileTarget = item.isHost
        ? `../social/host-home.html?host=${encodeURIComponent(item.name.toLowerCase())}`
        : `../social/user-home.html?user=${encodeURIComponent(item.id)}`;
      const avatarTarget = isLive ? liveTarget : profileTarget;
      const action = isLive
        ? `<button class="live-entry" type="button" data-live-target="${liveTarget}">直播中</button>`
        : "";
      return `<article class="result"><button class="avatar avatar-action" type="button" aria-label="进入${isLive ? "直播间" : item.isHost ? "主播主页" : "用户主页"}" data-avatar-target="${avatarTarget}">${item.avatar}</button><span class="result-info"><b>${item.name}</b>${item.isHost ? `<span>房间号：${item.roomId}</span>` : ""}</span>${action}</article>`;
    })
    .join("");
  if (managerMode)
    list.querySelectorAll("[data-manager-id]").forEach((item) => {
      item.onclick = () =>
        openManagerProfile(
          entries.find((entry) => entry.id === item.dataset.managerId),
        );
    });
  else
    list
      .querySelectorAll("[data-avatar-target],[data-live-target]")
      .forEach((item) => {
        item.onclick = () => {
          location.href =
            item.dataset.avatarTarget || item.dataset.liveTarget;
        };
      });
}
document.querySelector("#back").onclick = () => {
  location.href = managerMode
    ? `search.html?mode=manager&return=${encodeURIComponent(returnTarget)}&keyword=${encodeURIComponent(keyword)}`
    : `search.html?keyword=${encodeURIComponent(keyword)}`;
};
form.onsubmit = (event) => {
