const params = new URLSearchParams(location.search);
const managerMode = params.get("mode") === "manager";
const returnTarget =
  managerMode &&
  params.get("return") === "../host/moderator-management.html"
    ? "../host/moderator-management.html"
    : "";
const form = document.querySelector("#searchForm");
const input = document.querySelector("#keyword");
const historyKey = "luma-user-search-history-v1";
const defaultHistory = ["Sari", "620100", "Dewi", "唱歌直播"];
let searchHistory = defaultHistory.slice();
try {
  const savedHistory = JSON.parse(localStorage.getItem(historyKey));
  if (Array.isArray(savedHistory)) searchHistory = savedHistory.slice(0, 10);
} catch (_error) {}
input.value = params.get("keyword") || "";
if (managerMode) {
  document.querySelector("#historySection").classList.add("state-hide");
  input.placeholder = "搜索用户 ID";
  document.querySelector("#back").onclick = () => {
    location.href = returnTarget;
  };
} else
  document.querySelector("#back").onclick = () => {
    location.href = "live-plaza.html";
  };
requestAnimationFrame(() => input.focus());
function saveHistory() {
  try {
    localStorage.setItem(historyKey, JSON.stringify(searchHistory));
  } catch (_error) {}
}
function renderHistory() {
  const list = document.querySelector("#historyList");
  list.replaceChildren();
  searchHistory.forEach((keyword) => {
    const chip = document.createElement("div");
    chip.className = "history-chip";
    const searchButton = document.createElement("button");
    searchButton.className = "history-keyword";
    searchButton.type = "button";
    searchButton.textContent = keyword;
    searchButton.onclick = () => submitSearch(keyword);
    const deleteButton = document.createElement("button");
    deleteButton.className = "history-delete";
    deleteButton.type = "button";
    deleteButton.setAttribute("aria-label", `删除搜索历史 ${keyword}`);
    deleteButton.textContent = "×";
    deleteButton.onclick = () => {
      searchHistory = searchHistory.filter((item) => item !== keyword);
      saveHistory();
      renderHistory();
    };
    chip.append(searchButton, deleteButton);
    list.append(chip);
  });
  document
    .querySelector("#historyEmpty")
    .classList.toggle("state-hide", searchHistory.length > 0);
  document
    .querySelector("#clearHistory")
    .classList.toggle("state-hide", searchHistory.length === 0);
}
function submitSearch(rawKeyword) {
  const keyword = rawKeyword.trim();
  if (!keyword) {
    Luma.toast("请输入搜索内容");
    input.focus();
    return;
  }
  if (!managerMode) {
    searchHistory = [
      keyword,
      ...searchHistory.filter((item) => item !== keyword),
    ].slice(0, 10);
    saveHistory();
  }
  const query = new URLSearchParams({ keyword });
  if (managerMode) {
    query.set("mode", "manager");
    query.set("return", returnTarget);
  }
  location.href = `search-results.html?${query}`;
}
form.onsubmit = (event) => {
  event.preventDefault();
  submitSearch(input.value);
};
document.querySelector("#clearHistory").onclick = () => {
  searchHistory = [];
  saveHistory();
  renderHistory();
};
renderHistory();
Luma.registerStates({
  页面状态: {
    未输入: () => {
      input.value = "";
    },
    已输入: () => {
      input.value = "Sari";
    },
  },
  搜索历史: {
    有记录: () => {
      searchHistory = defaultHistory.slice();
      saveHistory();
      renderHistory();
    },
    已清空: () => {
      searchHistory = [];
      saveHistory();
      renderHistory();
    },
  },
});

