let swipeStartX = 0,
  swipeStartY = 0;
function closeSwiped(except) {
  members.querySelectorAll(".member.swiped").forEach((member) => {
    if (member !== except) member.classList.remove("swiped");
  });
}
members.querySelectorAll(".member").forEach((member) => {
  member.removeAttribute("onclick");
  member.onclick = () => {
    if (!member.classList.contains("swiped"))
      Luma.toast(`查看 ${member.dataset.name} 的资料`);
  };
  member.addEventListener(
    "touchstart",
    (event) => {
      if (event.target.closest(".member-action")) return;
      swipeStartX = event.touches[0].clientX;
      swipeStartY = event.touches[0].clientY;
    },
    { passive: true },
  );
  member.addEventListener(
    "touchend",
    (event) => {
      if (event.target.closest(".member-action")) return;
      const deltaX = event.changedTouches[0].clientX - swipeStartX,
        deltaY = event.changedTouches[0].clientY - swipeStartY;
      if (Math.abs(deltaX) <= Math.abs(deltaY) || Math.abs(deltaX) < 36)
        return;
      if (deltaX < 0) {
        closeSwiped(member);
        member.classList.add("swiped");
      } else member.classList.remove("swiped");
    },
    { passive: true },
  );
});
document.addEventListener("click", (event) => {
  if (!event.target.closest(".member")) closeSwiped();
});

members.querySelectorAll(".member").forEach((member) => {
  member.addEventListener("pointerdown", (event) => {
    if (event.target.closest(".member-action")) return;
    swipeStartX = event.clientX;
    swipeStartY = event.clientY;
  });
  member.addEventListener("pointerup", (event) => {
    if (event.target.closest(".member-action")) return;
    const deltaX = event.clientX - swipeStartX,
      deltaY = event.clientY - swipeStartY;
    if (Math.abs(deltaX) <= Math.abs(deltaY) || Math.abs(deltaX) < 36)
      return;
    if (deltaX < 0) {
      closeSwiped(member);
      member.classList.add("swiped");
    } else member.classList.remove("swiped");
  });
});
