const initialRange = { start: "2026-08-10", end: "2026-08-17" };
let appliedRange = { ...initialRange },
  draftRange = { ...initialRange },
  calendarMonth = { year: 2026, month: 7 },
  quickRange = "month";
const pad = (value) => String(value).padStart(2, "0");
const dateKey = (year, month, day) =>
  `${year}-${pad(month + 1)}-${pad(day)}`;
const parseDate = (value) => {
  const [year, month, day] = String(value).split("-").map(Number);
  return { year, month: month - 1, day };
};
const displayDate = (value) => LUMA_FORMAT.date(value);
const rangeText = (range) =>
  range.end && range.end !== range.start
