    : displayDate(range.start);
const quickRangeNames = {
  month: "本月",
  week: "本周",
  previousMonth: "上月",
  custom: "自定义",
};
const referenceDate = [...LUMA_MOCK.liveRecords].sort((left, right) =>
  right.date.localeCompare(left.date),
)[0].date;
const utcDateKey = (date) =>
  dateKey(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate());
function getQuickRange(type) {
  const { year, month, day } = parseDate(referenceDate),
    date = new Date(Date.UTC(year, month, day));
  if (type === "month")
    return {
      start: utcDateKey(new Date(Date.UTC(year, month, 1))),
      end: utcDateKey(new Date(Date.UTC(year, month + 1, 0))),
    };
  if (type === "previousMonth")
    return {
      start: utcDateKey(new Date(Date.UTC(year, month - 1, 1))),
      end: utcDateKey(new Date(Date.UTC(year, month, 0))),
    };
  const weekday = date.getUTCDay() || 7;
  return {
    start: utcDateKey(new Date(Date.UTC(year, month, day - weekday + 1))),
    end: utcDateKey(new Date(Date.UTC(year, month, day - weekday + 7))),
  };
}
