      ),
    );
}
function renderCalendar() {
  const firstDay = new Date(
      Date.UTC(calendarMonth.year, calendarMonth.month, 1),
    ).getUTCDay(),
    daysInMonth = new Date(
      Date.UTC(calendarMonth.year, calendarMonth.month + 1, 0),
    ).getUTCDate();
  const blanks = Array.from({ length: firstDay }, () => "<i></i>").join(
    "",
  );
  const days = Array.from({ length: daysInMonth }, (_, index) => {
    const day = index + 1,
      key = dateKey(calendarMonth.year, calendarMonth.month, day),
      selected = key === draftRange.start || key === draftRange.end,
      inRange =
        draftRange.start &&
        key >= draftRange.start &&
        key <= (draftRange.end || draftRange.start);
    return `<button type="button" class="${selected ? "selected" : inRange ? "in-range" : ""}" data-date="${key}" aria-pressed="${selected}">${day}</button>`;
  }).join("");
  pickerCalendar.innerHTML = `<div class="calendar-nav"><button type="button" id="previousMonth" aria-label="上个月">‹</button><b>${calendarMonth.year}年${calendarMonth.month + 1}月</b><button type="button" id="nextMonth" aria-label="下个月">›</button></div><div class="calendar-week"><span>日</span><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span></div><div class="calendar-days">${blanks}${days}</div>`;
  pickerCalendar.querySelector("#previousMonth").onclick = () =>
    changeMonth(-1);
  pickerCalendar.querySelector("#nextMonth").onclick = () =>
    changeMonth(1);
  pickerCalendar
    .querySelectorAll("[data-date]")
    .forEach(
      (button) =>
        (button.onclick = () => selectDate(button.dataset.date)),
    );
}
function changeMonth(offset) {
  calendarMonth.month += offset;
  if (calendarMonth.month < 0) {
    calendarMonth.year--;
    calendarMonth.month = 11;
  }
  if (calendarMonth.month > 11) {
    calendarMonth.year++;
    calendarMonth.month = 0;
  }
  renderCalendar();
}
function selectDate(value) {
  if (!draftRange.start || draftRange.end) {
    draftRange = { start: value, end: "" };
  } else if (value === draftRange.start) {
    draftRange = { start: value, end: "" };
  } else {
    draftRange =
      value > draftRange.start
        ? { start: draftRange.start, end: value }
        : { start: value, end: draftRange.start };
  }
  renderCalendar();
}
function parseDuration(value) {
  const match = String(value).match(/^(?:(\d+)h)?(?:(\d+)m)?$/);
  return match ? Number(match[1] || 0) * 60 + Number(match[2] || 0) : 0;
}
function renderSummary(range) {
  const end = range.end || range.start,
    records = LUMA_MOCK.liveRecords.filter(
      (record) => record.date >= range.start && record.date <= end,
    ),
    income = records.reduce(
      (total, record) => total + LUMA_FORMAT.parseDecimal(record.income),
      0,
    ),
    duration = records.reduce(
