      0,
    );
  recordSummary.innerHTML = `<div class="summary-metric"><span>收益</span><b>${LUMA_FORMAT.integer(income)}</b></div><div class="summary-metric"><span>总时长</span><b>${Math.floor(duration / 60)}h${duration % 60}m</b></div><div class="summary-metric"><span>直播场次</span><b>${records.length}</b></div>`;
}
function applyDateFilter(range) {
  const end = range.end || range.start;
  document
    .querySelectorAll(".record")
    .forEach((record) =>
      record.classList.toggle(
        "state-hide",
        record.dataset.date < range.start || record.dataset.date > end,
