var liveVisibleScope = document.querySelector("#liveVisibleScope"),
  livePlazaSwitch = document.querySelector("#livePlazaSwitch"),
  liveFanClubOnlySwitch = document.querySelector("#liveFanClubOnlySwitch"),
  livePlazaStorageKey = "luma-password-room-plaza-visible",
  liveFanClubStorageKey = "luma-password-room-fan-club-only";

function readLiveScopeSwitch(key, fallback) {
  var value = localStorage.getItem(key);
  return value === null ? fallback : value === "true";
}

function setLiveScopeSwitch(button, enabled) {
  button.classList.toggle("on", enabled);
  button.setAttribute("aria-checked", String(enabled));
}

function openLiveVisibleScope() {
  setLiveScopeSwitch(
    livePlazaSwitch,
    readLiveScopeSwitch(livePlazaStorageKey, true),
  );
  setLiveScopeSwitch(
    liveFanClubOnlySwitch,
    readLiveScopeSwitch(liveFanClubStorageKey, false),
  );
  liveVisibleScope.classList.remove("state-hide");
}

[livePlazaSwitch, liveFanClubOnlySwitch].forEach(function (button) {
  button.onclick = function () {
    if (
      button === liveFanClubOnlySwitch &&
      !button.classList.contains("on") &&
      !LUMA_MOCK.hostFanClubSettings
    )
      return Luma.toast("请先创建粉丝团");
    setLiveScopeSwitch(button, !button.classList.contains("on"));
  };
});
liveVisibleScope.querySelector("[data-close-live-scope]").onclick = function () {
  liveVisibleScope.classList.add("state-hide");
};
liveVisibleScope.onclick = function (event) {
  if (event.target === liveVisibleScope)
    liveVisibleScope.classList.add("state-hide");
};
document.querySelector("#saveLiveVisibleScope").onclick = function () {
  var fanClubOnly = liveFanClubOnlySwitch.classList.contains("on");
  localStorage.setItem(
    livePlazaStorageKey,
    String(livePlazaSwitch.classList.contains("on")),
  );
  localStorage.setItem(
    liveFanClubStorageKey,
    String(fanClubOnly),
  );
  liveVisibleScope.classList.add("state-hide");
  Luma.toast("访问范围已更新");
};
if (new URLSearchParams(location.search).get("view") === "visible-scope") {
