window.addEventListener("load", function () {
  var sheet = document.querySelector(".live-recharge-sheet"),
    recharge = window.LUMA_MOCK?.recharge;
  if (!sheet || !recharge) return;
  function node(tag, text, className) {
    var item = document.createElement(tag);
    if (text) item.textContent = text;
    if (className) item.className = className;
    return item;
  }
  function activity(data, label) {
    var button = node("button", "", "");
    button.type = "button";
    button.dataset.rechargePrice = data.price;
    button.append(node("i", label));
    button.append(node("b", data.coins + " 金币"));
    button.append(node("small", "额外赠送 " + data.bonus));
    button.append(node("strong", data.price));
    return button;
  }
  var activities = sheet.querySelector(".live-activity-row");
  activities.replaceChildren(
    activity(recharge.activity, recharge.activity.badge),
    activity(recharge.limited, recharge.limited.badge),
  );
  var packages = sheet.querySelector(".live-recharge-grid");
  packages.replaceChildren();
  recharge.packages.forEach(function (data) {
    var button = node("button", "", "");
    button.type = "button";
    button.dataset.rechargePrice = data.price;
    button.append(node("i", "金币"));
    button.append(node("b", data.coins + " 金币"));
    button.append(node("strong", data.price));
    packages.append(button);
  });
  sheet
    .querySelectorAll("[data-recharge-price]")
    .forEach(function (button) {
      button.onclick = function () {
        Luma.toast("发起 " + button.dataset.rechargePrice + " 支付");
      };
    });
});

