window.addEventListener("load", function () {
  var room = document.querySelector(".room");
  if (!room) return;

  var accessMask = document.createElement("section");
  accessMask.className = "room-access-mask state-hide";
  accessMask.setAttribute("role", "presentation");
  accessMask.innerHTML =
    '<div class="room-access-cover" aria-hidden="true"></div>' +
    '<section class="room-access-sheet room-access-password state-hide" data-access-sheet="password" role="dialog" aria-modal="true" aria-labelledby="passwordAccessTitle">' +
    '<button type="button" class="room-access-close" aria-label="关闭密码输入">×</button>' +
    '<h2 id="passwordAccessTitle">输入房间密码</h2>' +
    '<p class="room-access-subtitle">Lala · 粉丝专属夜</p>' +
    '<input type="password" inputmode="numeric" maxlength="12" placeholder="请输入密码" aria-label="房间密码，4-12 个数字">' +
    '<p class="room-access-password-error" aria-live="polite"></p>' +
    '<button type="button" class="room-access-primary" data-access-submit-password disabled>进入直播间</button>' +
    '</section>' +
    '<section class="room-access-sheet room-access-ticket state-hide" data-access-sheet="ticket" role="dialog" aria-modal="true" aria-labelledby="ticketAccessTitle">' +
    '<button type="button" class="room-access-close" aria-label="关闭购买门票">×</button>' +
    '<h2 id="ticketAccessTitle">购买门票</h2>' +
    '<p class="room-access-subtitle">Intan · 随机舞蹈</p>' +
    '<div class="room-access-ticket-item"><i>◆</i><div><b>本场直播门票</b><span>仅限当前场次</span></div><strong class="coin">10</strong></div>' +
    '<footer class="room-access-ticket-footer"><div class="room-access-balance"><span class="coin">12.580</span><button type="button" data-access-recharge aria-label="充值">+</button></div><button type="button" data-access-buy-ticket>购买</button></footer>' +
    '</section>' +
    '<section class="room-access-sheet room-access-fan-club state-hide" data-access-sheet="fan-club" role="dialog" aria-modal="true" aria-labelledby="fanClubAccessTitle">' +
    '<h2 id="fanClubAccessTitle">无法进入直播间</h2>' +
    '<p>访问直播间需先加入主播粉丝团</p>' +
    '<button type="button" class="room-access-primary" data-access-back-home>返回</button>' +
    '</section>' +
    '<section class="room-access-sheet room-access-blocked state-hide" data-access-sheet="blocked" role="dialog" aria-modal="true" aria-labelledby="blockedAccessTitle">' +
    '<h2 id="blockedAccessTitle">无法进入直播间</h2>' +
    '<p>与主播存在拉黑或被踢出关系</p>' +
    '<button type="button" class="room-access-primary" data-access-back-home>返回</button>' +
    '</section>';
  room.append(accessMask);

  var patrolNotice = document.createElement("section");
  patrolNotice.className = "room-patrol-notice state-hide";
  patrolNotice.setAttribute("role", "status");
  patrolNotice.innerHTML =
    "<b>巡房中</b><span>本次巡房期间，主播和房管无法将你拉黑或踢出</span>";
  room.append(patrolNotice);

  var passwordInput = accessMask.querySelector(".room-access-password input"),
    passwordError = accessMask.querySelector(".room-access-password-error"),
    passwordSubmit = accessMask.querySelector("[data-access-submit-password]");

  function closeAccessSheet() {
    accessMask.classList.add("state-hide");
    accessMask.querySelectorAll("[data-access-sheet]").forEach(function (sheet) {
      sheet.classList.add("state-hide");
    });
  }
  function openAccessSheet(type) {
    closeAccessSheet();
    patrolNotice.classList.add("state-hide");
    accessMask.classList.remove("state-hide");
    accessMask.querySelector('[data-access-sheet="' + type + '"]').classList.remove("state-hide");
    if (type === "password") {
      passwordInput.value = "";
      passwordError.textContent = "";
      passwordSubmit.disabled = true;
      passwordInput.focus();
    }
  }
  function returnToPlaza() {
    window.parent.postMessage(
      { type: "luma-page", file: "live-plaza.html" },
      "*",
    );
    location.href = "../home/live-plaza.html";
  }
  function returnToSource() {
    if (document.referrer.includes("/pages/")) history.back();
    else returnToPlaza();
  }
  function grantRoomAccess(message) {
    closeAccessSheet();
    try {
      history.replaceState(null, "", location.pathname);
    } catch (_error) {}
    Luma.toast(message);
  }

  accessMask.querySelectorAll(".room-access-close").forEach(function (button) {
    button.onclick = returnToPlaza;
  });
  accessMask.onclick = function (event) {
    if (event.target === accessMask) returnToPlaza();
  };
  passwordInput.oninput = function () {
    passwordSubmit.disabled = !passwordInput.value.trim();
    passwordError.textContent = "";
  };
  passwordInput.onkeydown = function (event) {
    if (event.key === "Enter" && !passwordSubmit.disabled)
      passwordSubmit.click();
  };
  passwordSubmit.onclick = function () {
    if (!/^\d{4,12}$/.test(passwordInput.value)) {
      passwordError.textContent = "密码必须是4-12个数字";
      return;
    }
    if (passwordInput.value !== "123456") {
      passwordError.textContent = "密码错误，请重新输入";
      return;
    }
    grantRoomAccess("密码验证成功");
  };
  accessMask.querySelector("[data-access-recharge]").onclick = function () {
    Luma.toast("打开充值");
  };
  accessMask.querySelector("[data-access-buy-ticket]").onclick = function () {
    grantRoomAccess("购买门票成功");
  };
  accessMask.querySelectorAll("[data-access-back-home]").forEach(function (button) {
    button.onclick = returnToSource;
  });
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !accessMask.classList.contains("state-hide"))
      returnToPlaza();
  });

  Luma.registerStates({
    房间访问: {
      "密码房-访问受限": function () {
        openAccessSheet("password");
      },
      "门票房-访问受限": function () {
        openAccessSheet("ticket");
      },
      "非粉丝团成员-访问受限": function () {
        openAccessSheet("fan-club");
      },
      "被拉黑或踢出-访问受限": function () {
        openAccessSheet("blocked");
      },
    },
  });
  var requestedAccess = new URLSearchParams(location.search).get("access");
  if (!requestedAccess || requestedAccess === "normal") {
    closeAccessSheet();
  } else if (requestedAccess === "patrol") {
    closeAccessSheet();
    patrolNotice.classList.remove("state-hide");
  } else if (["password", "ticket", "fan-club", "blocked"].includes(requestedAccess))
    openAccessSheet(requestedAccess);
});

