let blacklist = [...window.LUMA_MOCK.blacklist];
let pendingName = "";
const list = document.querySelector("#list"),
  confirmOne = document.querySelector("#confirmOne");
function render() {
  list.replaceChildren();
  if (!blacklist.length) {
    const empty = document.createElement("p");
    empty.className = "empty";
    empty.textContent = "暂无黑名单用户";
    list.append(empty);
    return;
  }
  blacklist.forEach((user) => {
    const item = document.createElement("article");
    item.className = "item";
    item.innerHTML =
      '<i class="avatar"></i><b></b><button class="remove" type="button">移除</button>';
    item.querySelector(".avatar").textContent = user.avatar;
    item.querySelector("b").textContent = user.name;
    item.querySelector(".remove").onclick = () => openConfirm(user.name);
    list.append(item);
  });
}
function setDialog(dialog, title, detail) {
  dialog.querySelector("b").textContent = title;
  dialog.querySelector("p").textContent = detail;
}
function closeConfirm() {
  confirmOne.classList.add("state-hide");
  pendingName = "";
}
function openConfirm(name) {
  pendingName = name;
  setDialog(
    confirmOne,
    `确认移除 ${name}？`,
    "移除后将恢复正常互动权限。",
  );
  confirmOne.classList.remove("state-hide");
}
document
  .querySelectorAll("[data-cancel]")
  .forEach((button) => (button.onclick = closeConfirm));
confirmOne.querySelector("[data-confirm]").onclick = () => {
  const name = pendingName;
  blacklist = blacklist.filter((user) => user.name !== name);
  closeConfirm();
  render();
  Luma.toast(`已将 ${name} 移出黑名单`);
};
render();

const contacts = LUMA_MOCK.customerService;
document.querySelector("#whatsapp").textContent = contacts.whatsapp;
document.querySelector("#email").textContent = contacts.email;

async function copyContact(value) {
  try {
    await navigator.clipboard.writeText(value);
  } catch (_) {
    const input = document.createElement("textarea");
    input.value = value;
    document.body.append(input);
    input.select();
    document.execCommand("copy");
    input.remove();
  }
  Luma.toast("已复制");
}

document.querySelectorAll("[data-copy]").forEach((button) => {
  button.onclick = () => copyContact(contacts[button.dataset.copy]);
});

const decoration = LUMA_MOCK.myDecorations;
const ownedPanel = document.querySelector("#ownedPanel"),
  ownedProducts = document.querySelector("#ownedProducts"),
  medalTab = document.querySelector("#medalTab"),
  storePanel = document.querySelector("#storePanel"),
  products = document.querySelector("#products"),
  purchaseMask = document.querySelector("#purchaseMask"),
  purchasePrimary = document.querySelector("#purchasePrimary"),
  purchaseSecondary = document.querySelector("#purchaseSecondary");
let ownedType = "avatarFrame",
  storeType = "avatarFrame",
  showInsufficientNext = false;
const purchaseStorageKey = "luma-decoration-purchases-v1",
  equippedStorageKey = "luma-decoration-equipped-v1";
let purchasedIds = [],
  equippedProducts = {};
try {
  purchasedIds = JSON.parse(sessionStorage.getItem(purchaseStorageKey) || "[]");
  equippedProducts = JSON.parse(sessionStorage.getItem(equippedStorageKey) || "{}");
} catch (_) {}
if (!Object.hasOwn(equippedProducts, "avatarFrame")) equippedProducts.avatarFrame = decoration.avatarFrames.find((item) => item.equipped && !item.expired)?.id || "";
if (!Object.hasOwn(equippedProducts, "chatBubble")) equippedProducts.chatBubble = decoration.chatBubbles.find((item) => item.equipped && !item.expired)?.id || "";
if (!Array.isArray(equippedProducts.medal)) {
  const legacyMedal = equippedProducts.medal;
  equippedProducts.medal = decoration.medals.filter((item) => item.equipped && !item.expired).map((item) => item.id);
  if (legacyMedal && !equippedProducts.medal.includes(legacyMedal)) equippedProducts.medal.push(legacyMedal);
}
const purchased = new Set(Array.isArray(purchasedIds) ? purchasedIds : []);
document.querySelector("#avatar").textContent =
  LUMA_MOCK.myProfile.avatar;
function renderEquippedMedals() {
  const allMedals = [...decoration.medals, ...decoration.shop.filter((item) => item.type === "medal" && purchased.has(item.id))];
  document.querySelector("#medals").innerHTML = allMedals
    .filter((item) => equippedProducts.medal.includes(item.id))
    .map((item, index) => `<i title="${item.name}">勋章 ${index + 1}</i>`)
    .join("");
}
function coins(value) {
  return Number(value).toLocaleString("id-ID");
}

function renderOwned() {
  const source = ownedType === "avatarFrame" ? decoration.avatarFrames : ownedType === "chatBubble" ? decoration.chatBubbles : decoration.medals;
  const purchasedItems = decoration.shop
    .filter((item) => item.type === ownedType && purchased.has(item.id))
    .map((item) => ({ ...item, acquiredAt: `9999-${String(purchasedIds.indexOf(item.id)).padStart(4, "0")}` }));
  const isEquipped = (item) => ownedType === "medal"
    ? equippedProducts.medal.includes(item.id)
    : equippedProducts[ownedType] === item.id;
  const items = [...source, ...purchasedItems].sort((a, b) => {
    const rank = (item) => item.expired ? 2 : isEquipped(item) ? 0 : 1;
    return rank(a) - rank(b) || String(b.acquiredAt || "").localeCompare(String(a.acquiredAt || ""));
  });
  ownedProducts.innerHTML = items.map((item) => {
    const status = item.expired ? "失效" : isEquipped(item) ? "已佩戴" : "佩戴";
    const visual = ownedType === "avatarFrame"
      ? `<i class="owned-visual avatar-frame"><i class="avatar">${LUMA_MOCK.myProfile.avatar}</i></i>`
      : ownedType === "chatBubble"
        ? `<i class="owned-visual chat-bubble">hello～</i>`
        : `<i class="owned-visual medal">${item.mark}</i>`;
    return `<button class="owned-item ${item.expired ? "expired" : isEquipped(item) ? "equipped" : ""}" ${item.expired ? "disabled" : ""} type="button" data-owned-id="${item.id}">${visual}<b>${item.name}</b><small>${item.validity}</small><small class="wear-state">${status}</small></button>`;
  }).join("");
  medalTab.textContent = `勋章${equippedProducts.medal.length}/5`;
  renderEquippedMedals();
}

function switchMode(mode) {
  document.querySelectorAll("[data-decoration-tab]").forEach(function (button) {
    button.classList.toggle("active", button.dataset.decorationTab === mode);
  });
  ownedPanel.classList.toggle("state-hide", mode !== "owned");
  storePanel.classList.toggle("state-hide", mode !== "store");
