function showPurchase(product, state) {
  const insufficient = state === "insufficient";
  document.querySelector("#dialogVisual").textContent = product.mark;
  document.querySelector("#dialogVisual").classList.toggle("state-hide", insufficient);
  const purchaseCopy = document.querySelector("#purchaseCopy");
  if (insufficient) purchaseCopy.innerHTML = '<span>金币余额（<span class="coin">1000</span>）不足，请先充值</span>';
  else purchaseCopy.textContent = `${product.name} · ${product.validity}`;
  document.querySelector("#purchasePrice").textContent = `◆ ${coins(product.price)}`;
  document.querySelector("#purchasePriceRow").classList.toggle("state-hide", insufficient);
  purchaseSecondary.textContent = "取消";
  purchasePrimary.textContent = insufficient ? "去充值" : "购买";
  purchaseMask.setAttribute("aria-label", insufficient ? "金币不足" : "购买装扮");
  purchaseMask.classList.remove("state-hide");
  function completePurchase() {
    purchased.add(product.id);
    purchasedIds = [...purchased];
    sessionStorage.setItem(purchaseStorageKey, JSON.stringify(purchasedIds));
    renderStore();
    document.querySelector("#dialogVisual").classList.add("state-hide");
    document.querySelector("#purchaseCopy").textContent = "购买成功";
    document.querySelector("#purchasePriceRow").classList.add("state-hide");
    purchaseSecondary.textContent = "继续购买";
    purchasePrimary.textContent = "去佩戴";
    purchaseMask.setAttribute("aria-label", "购买成功");
    purchaseSecondary.onclick = function () {
      purchaseMask.classList.add("state-hide");
    };
    purchasePrimary.onclick = function () {
      ownedType = product.type;
      document.querySelectorAll("[data-owned-type]").forEach(function (item) {
        item.classList.toggle("active", item.dataset.ownedType === ownedType);
      });
      purchaseMask.classList.add("state-hide");
      switchMode("owned");
      window.scrollTo(0, 0);
    };
  }
  purchaseSecondary.onclick = function () {
    purchaseMask.classList.add("state-hide");
  };
  purchasePrimary.onclick = function () {
    if (insufficient) {
      location.href = "../wallet/recharge.html";
      return;
    }
    completePurchase();
  };
}

