const profileMock = window.LUMA_MOCK.myProfile,
  initialProfile = { ...profileMock },
  validationResults = ["success", "invalid", "network"];
const avatarFile = document.querySelector("#avatarFile"),
  avatarButton = document.querySelector("#avatarButton"),
  coverFile = document.querySelector("#coverFile"),
  coverButton = document.querySelector("#coverButton"),
  coverPreview = document.querySelector("#coverPreview"),
  nickname = document.querySelector("#nickname"),
  gender = document.querySelector("#gender"),
  region = document.querySelector("#region"),
  birthday = document.querySelector("#birthday"),
  signature = document.querySelector("#signature"),
  save = document.querySelector("#save"),
  validationLoading = document.querySelector("#validationLoading");
let avatarChanged = false,
  validationResultIndex = 0,
  isValidating = false,
  riskValidationDemoActive = false;
function fillProfile() {
  nickname.value = profileMock.name;
  gender.value = profileMock.gender;
  region.value = profileMock.region;
  birthday.value = profileMock.birthday;
  signature.value = profileMock.signature;
  document.querySelector("#userId").value = profileMock.id;
  document.querySelector("#avatarText").textContent = profileMock.avatar;
  coverPreview.style.backgroundImage = "";
  avatarChanged = false;
  syncForm();
}
function syncForm() {
  save.disabled = !nickname.value.trim();
}
avatarButton.onclick = () => avatarFile.click();
avatarFile.onchange = () => {
  if (!avatarFile.files?.[0]) return;
  avatarChanged = true;
  riskValidationDemoActive = true;
  document.querySelector("#avatarText").textContent = "新";
  Luma.toast("已选择新头像");
};
coverButton.onclick = () => coverFile.click();
coverFile.onchange = () => {
  const file = coverFile.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    coverPreview.style.backgroundImage = `url("${reader.result}")`;
    Luma.toast("已选择新背景图");
  };
  reader.readAsDataURL(file);
};
nickname.addEventListener("input", () => {
  riskValidationDemoActive = true;
  syncForm();
});
[gender, region, birthday, signature].forEach((element) =>
  element.addEventListener("input", syncForm),
);
function saveDirectFields() {
  profileMock.gender = gender.value;
  profileMock.region = region.value;
  profileMock.birthday = birthday.value;
  profileMock.signature = signature.value;
}
function resetProfile() {
  Object.assign(profileMock, initialProfile);
  fillProfile();
  validationResultIndex = 0;
  riskValidationDemoActive = false;
  setValidationLoading(false);
}
function saveRiskFields() {
  profileMock.name = nickname.value.trim();
  if (avatarChanged)
    profileMock.avatar = document.querySelector("#avatarText").textContent;
  avatarChanged = false;
}
function setValidationLoading(loading) {
  isValidating = loading;
  validationLoading.classList.toggle("state-hide", !loading);
  document.querySelector(".screen").setAttribute("aria-busy", String(loading));
  save.disabled = loading || !nickname.value.trim();
}
save.onclick = async () => {
  if (save.disabled || isValidating) return;
  const changesRiskContent =
    riskValidationDemoActive ||
    avatarChanged ||
    nickname.value.trim() !== profileMock.name;
  if (!changesRiskContent) {
    saveDirectFields();
    Luma.toast("资料已保存");
    return;
  }
  const result = validationResults[validationResultIndex];
  validationResultIndex =
    (validationResultIndex + 1) % validationResults.length;
  setValidationLoading(true);
  await new Promise((resolve) => setTimeout(resolve, 3000));
  setValidationLoading(false);
  if (result === "invalid") {
    Luma.toast("头像或昵称不合规");
    return;
  }
  if (result === "network") {
    Luma.toast("网络异常，请重试");
    return;
  }
  saveDirectFields();
  saveRiskFields();
  Luma.toast("资料已保存");
};
