const input = document.querySelector("#input"),
  send = document.querySelector("#send"),
  chat = document.querySelector("#chat");
let sentCount = 1,
  failNext = false,
  blocked = false;
Luma.rejectBlockedMessage = (item) => {
  if (!blocked) return false;
  item.classList.add("blocked");
  item.querySelector(".bubble").insertAdjacentHTML("afterend", '<span class="blocked-mark" aria-label="发送失败">❕&#xfe0e;</span>');
  item.insertAdjacentHTML("beforeend", '<p class="blocked-reason">消息发送失败，对方拒收</p>');
  return true;
};
function sync() {
  send.disabled = !input.value.trim();
}
function append() {
  const text = input.value.trim();
  if (!text) return;
  if (!blocked && sentCount >= 3) return Luma.toast("非好友最多发送三条");
  const item = document.createElement("div");
  item.className = "msg me";
  item.innerHTML = `${failNext && !blocked ? '<button class="msg-failed" type="button" title="发送失败，点击重试" aria-label="发送失败，点击重试">!</button>' : ""}<p class="bubble"></p><i class="avatar">安</i>`;
  item.querySelector(".bubble").textContent = text;
  Luma.rejectBlockedMessage(item);
  chat.append(item);
  if (!failNext && !blocked) sentCount += 1;
  input.value = "";
  sync();
  input.focus();
  if (failNext && !blocked) Luma.toast("发送失败");
  failNext = false;
  item.scrollIntoView({ block: "end" });
}
chat.addEventListener("click", (event) => {
  const retry = event.target.closest(".msg-failed");
  if (!retry) return;
  if (blocked) {
    Luma.rejectBlockedMessage(retry.parentElement);
    retry.remove();
    return;
  }
  if (sentCount >= 3) return Luma.toast("非好友最多发送三条");
  retry.remove();
  sentCount += 1;
  sync();
  Luma.toast("发送成功");
});
input.addEventListener("input", sync);
input.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.shiftKey) {
    e.preventDefault();
    append();
  }
});
send.onclick = append;
Luma.registerStates({
  消息发送: {
    正常: () => { failNext = false; blocked = false; },
    发送失败: () => { failNext = true; blocked = false; },
    拉黑关系: () => { failNext = false; blocked = true; },
  },
});

