  blacklistNotice.classList.toggle("state-hide", !isBlacklisted);
  addFriendButton.classList.toggle(
    "state-hide",
    isBlacklisted || isFriend,
  );
  deleteFriendButton.classList.toggle("state-hide", !isFriend);
  if (isBlacklisted) {
    moreSheet.classList.add("state-hide");
    deleteConfirm.classList.add("state-hide");
    blockConfirm.classList.add("state-hide");
  }
};
const setFollowState = (isFollowed) => {
  followButton.classList.toggle("is-following", isFollowed);
  followButton.querySelector("b").textContent = isFollowed ? "✓" : "+";
  followButton.querySelector("span").textContent = isFollowed
    ? "已关注"
    : "关注";
};
setFollowState(Boolean(userProfile.isFollowed));
setRelationshipState(
  userProfile.isBlacklisted
    ? "blacklist"
    : userProfile.isFriend
      ? "friend"
      : "nonfriend",
);
followButton.onclick = () => {
  const isFollowed = !followButton.classList.contains("is-following");
  setFollowState(isFollowed);
  Luma.toast(isFollowed ? `已关注 ${userProfile.name}` : "已取消关注");
};
addFriendButton.onclick = () => Luma.toast("已发送好友申请");
document.querySelector("[data-message]").onclick = () =>
  (location.href = "direct-message.html");
document.querySelector("[data-more]").onclick = () =>
  moreSheet.classList.remove("state-hide");
document.querySelector("[data-close-more]").onclick = () =>
  moreSheet.classList.add("state-hide");
document.querySelector("[data-report]").onclick = () => {
  moreSheet.classList.add("state-hide");
  Luma.toast("已提交举报");
};
deleteFriendButton.onclick = () => {
  moreSheet.classList.add("state-hide");
  deleteConfirm.classList.remove("state-hide");
};
document.querySelector("[data-cancel-delete]").onclick = () =>
  deleteConfirm.classList.add("state-hide");
document.querySelector("[data-confirm-delete]").onclick = () => {
  deleteConfirm.classList.add("state-hide");
  setRelationshipState("nonfriend");
  Luma.toast("已删除好友");
};
document.querySelector("[data-block]").onclick = () => {
  moreSheet.classList.add("state-hide");
  blockConfirm.querySelector("b").textContent =
    `确认拉黑 ${userProfile.name}？`;
  blockConfirm.classList.remove("state-hide");
};
document.querySelector("[data-cancel-block]").onclick = () =>
  blockConfirm.classList.add("state-hide");
document.querySelector("[data-confirm-block]").onclick = () => {
  setFollowState(false);
  setRelationshipState("blacklist");
  Luma.toast(`已拉黑 ${userProfile.name}`);
};
Luma.registerStates({
  好友关系: {
    非好友: () => setRelationshipState("nonfriend"),
    好友: () => setRelationshipState("friend"),
    黑名单: () => setRelationshipState("blacklist"),
  },
});

